-- Generated by `make quests-export-gossip-text`; do not edit.
--
-- frFR gossip text for every line, pointing at the file each line is named after, so a
-- client in frFR finds gossip whatever language its packs speak. See
-- pipelines/quests/tts_cli/gossip_text.py.
if not SpokenGossipEnv then return end
-- DataModules, in Spoken's dialogue core, looks it up there.
setfenv(1, SpokenGossipEnv.Core)

if GetLocale() ~= "frFR" then
    return
end

GossipText = {
    GossipLookupByNPCID = {
        [68] = {
            ["$gUn:Une; enfant de la nature, n'est-ce pas ? Alors, vous n'avez qu'à vous rendre au puits de lune se trouvant dans le Parc."] = "a63f0a77a472eab18caf48ea8320d27e",
            ["Ah, la Rose dorée, ses lits moelleux, ses bains chauds... Rien que d'y penser, je bâille... Vous avez de la chance si vous vous y rendez. Vous la trouverez à l'ouest du Quartier commerçant. Des oreillers à plumes, des couvertures bien chaudes... ::bâille::"] = "e84a11ab6b3896ecf97c8adfbc08636c",
            ["Ah, vous cherchez Lucan Cordell. Il tient une échoppe dans le Quartier de la magie. C'est sur le chemin de la Prison."] = "e3f9bcedb2188218c92b8b8fb1e8eb6a",
            ["Ahhh, vous recherchez le Centre d’accueil des visiteurs de Stormwind. Il s’agit du premier bâtiment sur votre gauche lorsque vous passez les portes de la Vallée des Héros."] = "646cbbc2bf91bdaa020beb25f4e0a678",
            ["Ahhh, vous êtes à la recherche de Dungar Longdrink. Il possède quelques-uns des gryphons les plus rapides de ce côté de Khaz Modan ! Vous pourrez le trouver sur les remparts dans le Quartier commerçant."] = "a36856bf0646fdd5ce14e1bbdbeab7a2",
            ["Allez voir la caserne dans la Vieille ville ou la taverne du Cochon siffleur. Si vous vous rendez à la taverne, soyez-en $gsûr:sûre;, vous goûterez quelques-uns des breuvages les plus raffinés. Ils font honte aux bières des nains, je vous le dis."] = "c621f0b9a4a6a6290dd5972a302122fc",
            ["Alors comme ça, vous voilà « Défenseur de l’Alliance », hein ? Bon, je suppose que vous allez vouloir faire un tour au Hall des Champions. C’est dans la Vieille Ville, mais ils ne vous laissent pas entrer si vous n’êtes pas officier. Vous risquez de devoir vous résigner à parler à l’officier Areyn, dehors. Et maintenant, dégagez."] = "33278f8101e800c93fc3d2385cfed699",
            ["Alors, il faut que vous parliez à Thelman Slatefist. Vous le trouverez dans l'entourage du roi, au donjon de Stormwind."] = "bcfcce27aafd9e54ef3d2fcdb27f4139",
            ["Bah, les voleurs n’ont rien fait à part rendre notre travail plus difficile. Si seulement je pouvais chasser Osborne et Mathias de la Vieille ville pour les amener directement à la Prison."] = "6e24adae0babfe7f1e128960d09c55af",
            ["C'est bien des nains, ça, nous envoyer un spécialiste d'Ironforge pour nous apprendre à miner. C'est pourtant pas difficile de casser des cailloux. Mais bon, puisqu'il est là, c'est sans doute à lui que vous devez parler. Il s'appelle Gelman et il réside dans le Quartier des nains."] = "64070f95813e914bdca6f15e390c919e",
            ["Ce fichu Leland, tout ce qu'il fait, c'est rester assis sur le dock, à côté du Quartier commerçant, et pêcher toute la journée. J'espère qu'il est bon, vu le temps qu'il y passe. Si vous voulez apprendre, allez lui parler."] = "2472ef40c4054390e47d26a2790dcef8",
            ["Ce que la ligue d'Arathor tente de faire au bassin d'Arathi est admirable.  Quel dommage que ces horreurs de morts-vivants et leurs amis de la Horde se mettent en travers de leur route.  Partez pour le donjon de Stormwind.  Dame Hoteshem vous attend dans la salle d'audience du roi.  Elle peut vous aider à vous rendre au bassin d'Arathi."] = "adb9b1e902dc3d39490b7c0e4c0e67cd",
            ["Comment ? Je n’ai jamais entendu parler de maîtres des démonistes à Stormwind.   Cependant... Quelques signes d’activité démoniaque ont bien été observés là-bas, au niveau de l’Agneau assassiné, dans le quartier des mages. Je pense que vous pourriez aller vérifier."] = "f6a52f523eecff532c9530eae7d0e89a",
            ["Dans le quartier des Mages, il y a une petite échoppe appelée 'Tout pour l'alchimiste'. Vous verrez toutes sortes d'étranges boutiques tout au long de votre chemin dans le quartier des Mages, mais si vous restez sur le cercle extérieur, vous ne pouvez pas la rater."] = "8651024fca6f7bd42a0336d52e7d69fc",
            ["Des démonistes, hein ? Ne dites pas que je vous ai parlé, mais il paraît que ces types se rassemblent à l'Agneau assassiné, dans le quartier des mages."] = "f05de425d7bd02752037b8477cf01b53",
            ["Des gryphons, hein ? Je ne me suis jamais soucié de ces créatures mais chacun ses goûts.  Vous pourrez trouver Dungar Longdrink sur les remparts dans le Quartier commerçant."] = "258744fe85450f544093d5fd17856341",
            ["Eh bien eh bien, on fait son chemin dans le monde, on dirait ? Vous cherchez le Hall des Champions. Vous le trouverez à l’extrémité sud-est de la Vieille Ville. Si vous êtes officier, vous pourrez y entrer. Sinon, il faudra que vous parliez à l’officier Areyn, dehors. Bonne chance !"] = "a0e2103ae01da9c6c1707056a504c6ae",
            ["Envie d’apprendre le travail du cuir ? Simon Tanner serait en mesure de vous enseigner cet art. Vous pouvez le trouver dans la vieille ville, dans la boutique 'Au cuir protecteur'."] = "52ef93000b10574ffb40f6f451597e26",
            ["Et j’aimerais me joindre à vous, $N. Rendez-vous au donjon de Stormwind. Vous trouverez Thelman Slatefist dans la salle d’audience du roi. Il vous aidera à vous rendre dans la vallée d’Alterac."] = "5da822272073a4d726872184c3421ca6",
            ["Gelman Stonehand serait la personne à qui vous devriez parler. Je pense qu’il possède une maison plus haut dans le quartier des nains mais je ne me souviens plus de l’endroit exact. Je chercherais dans les environs, à votre place."] = "8f8f48c440d58b1a783b868dd9222e74",
            ["Il n'y a pas de meilleur endroit pour apprendre les Premiers soins que sous l'œil attentif de Shaina Fuller, à la Cathédrale de la Lumière.   Pour y aller, cherchez les toits jaunes, ou la tour de la Cathédrale elle-même. On la voit d'à peu près partout dans la ville."] = "b1be3018807cc2da500145c8c2b10794",
            ["Il se trouve dans le Quartier commerçant, $gcitoyen:citoyenne;. Presque en face de l’entrée de Stormwind."] = "568c01f3e19d99d5f41ea3aac2056ebe",
            ["Il y a une boîte aux lettres entre la banque de Stormwind et l'auberge de la Rose dorée, dans le Quartier commerçant."] = "bb63ff9d75c7726f1d06e21fe2021b8b",
            ["Je ne sais pas comment ils font... Ces boîtes aux lettres doivent être des portails magiques ou je ne sais quoi. Je vois des gens s'amasser autour de la boîte aux lettres, à côté de la banque, toute la journée, et ils tirent des épées, des boucliers et des armures de cette petite boîte !"] = "b4b551dc6175faa3e32ad05a88b10b09",
            ["Je vous suggérerais de jeter un oeil dans la Cathédrale de la Lumière située sur la place de la Cathédrale."] = "7c15eb60533829779dc9fd0c60d26a6a",
            ["Jenova Stoneshield, dans le quartier des nains, est la personne que vous cherchez. Elle s'occupe des familiers des chasseurs quand ils se rendent chez son père pour y poursuivre leur formation."] = "9654c77653b91d446f531295982fbec7",
            ["L'endurance de Woo Ping est tout simplement incroyable. Quand je l'ai observé s'entraîner pendant des heures d'affilée, j'avais vraiment mal pour le mannequin d'entraînement. Je ne connais personne de mieux placé pour vous entraîner au combat armé."] = "312810e5deb14cd60aa19428f7f51227",
            ["La Cathédrale de la Lumière est le centre de toutes les pratiques de guérison de Stormwind. Là-bas, vous trouverez Shaina Fuller, elle pourra vous aider à apprendre cet art."] = "fd43bf9ef9a4ea5b42ea21a6017c205b",
            ["La Salle des dépôts de Stormwind est située à l'entrée du Quartier commerçant de Stormwind. Quand vous en aurez assez de compter votre argent, n'oubliez pas de vous arrêter à la Rose dorée pour prendre un verre."] = "554b8726d09d342022c5c7eaf5a9818e",
            ["La banque de Stormwind se situe dans le Quartier commerçant, juste au nord-ouest des portes de la ville. Laissez-moi vous montrer sur votre carte."] = "8fedf8298f3edb222d5b5f4355c58675",
            ["La cathédrale de la Lumière, sur la place de la Cathédrale, est le domaine des prêtres de Stormwind. Là-bas, vous trouverez la grande prêtresse Laurena."] = "bb897a746e8a30c2b211e9076b6a286d",
            ["La vieille ville est l’endroit où vous devrez vous rendre si vous voulez trouver des voleurs. C'est au nord-est de Stormwind."] = "cd52082b0fdc76c7dded230c974a2ebf",
            ["Laurena est la grande prêtresse de Stormwind. Vous pourrez la trouver dans la cathédrale de la Lumière, située sur la place de la Cathédrale."] = "4a22a1b67aa8fe418d517ebb0e371796",
            ["Le Maître des Ingénieurs de Stormwind est un gnome ingénieux du nom de Lilliam Sparkspindle. Vous pouvez le trouver au fond du quartier des nains."] = "05e90b70ee82c6ab15e68fec597454c2",
            ["Le Parc est l’endroit où vous devez vous rendre si vous recherchez des maîtres des druides. Theridan et Maldryn se trouvent habituellement à proximité du puits de lune, au centre du quartier."] = "6ca4fdf838b083f58d40a21536adeaed",
            ["Le fort d’Aile-argent a bien besoin de renforts, en vérité. Allez au donjon de Stormwind et parlez à Elfarran."] = "ab67b49961ce98725cccb8a6b0e8e7ef",
            ["Les Textiles Duncan emploient un des meilleurs tailleurs de Stormwind, Georgio Bolero. Partez à la recherche de cette boutique dans le quartier des mages."] = "8706ad14fe81bd7bfe9d6986ff68ed63",
            ["Les guerriers se trouvent habituellement soit à la taverne du Cochon siffleur, soit à la caserne dans la Vieille ville. Cependant, vous aurez plus de chances à la taverne."] = "9434f3b21efa2de084243d600d530ff5",
            ["Les magi se rassemblent dans le Sanctuaire du sorcier, dans le quartier des mages. Ils ont une sacrée belle tour, là-bas ! Nos quartiers ont l’air de taudis de paysans à côté."] = "338c8fab07f57033e48217d5973c15df",
            ["Les sentinelles d’Aile-argent ont besoin de toute l’aide que l’on peut leur apporter dans leur combat contre les voltigeurs Warsong. $N, si vous souhaitez les aider, allez au donjon de Stormwind et parlez à Elfarran."] = "a28ad28e180fb23f6b2f30a8926dd8d3",
            ["Lucan Cordell tient une petite boutique sur le canal, non loin de la Prison. Je suis sûr qu’il sera en mesure de vous apprendre l’art de l’enchantement."] = "91e3f367dbb0e83b362a5880d1271dc4",
            ["Maître Woo Ping connaît presque toutes les armes créées en ce monde. Il est particulièrement redoutable en combat à l'épée. Il passe pas mal de temps à l'Arsenal de Weller, attendant de nouvelles livraisons d'armes, si vous voulez qu'il vous entraîne."] = "ea46258d498568523f3fadf071cc9af0",
            ["Oh, vous êtes à la recherche d’un apprentissage des arcanes, n’est-ce pas ? Il n’y a alors pas de meilleur endroit que le Sanctuaire du Sorcier, dans le quartier des mages."] = "0493aff58b480f500d524b265550d281",
            ["Oh, ça me fait penser, il faut que je fasse réparer mes bottes-fusées. Faites-moi confiance, les bottes-fusées et les gryphons font mauvais ménage.    Oh, mais vous avez besoin d'aide... Allez en direction du quartier des nains, et vous y trouverez au fond Lilliam Sparkspindle."] = "bb3fee63f3293484e591674a691d3c88",
            ["On dirait bien que vous souhaitez vous entretenir avec Maginor Dumas ! Il se trouve généralement dans le Sanctuaire du Sorcier, dans le quartier des mages. Bien sûr, on ne sait jamais quand et où ces magi se téléportent ailleurs."] = "fa0d9c855011039c74c70b23db0b82ea",
            ["On peut boire un verre dans de nombreux établissements de Stormwind, mais il n'en est qu'un où on peut passer la nuit. Dirigez-vous vers la Rose dorée dans le Quartier commerçant. Il paraît que le coût d'une chambre est raisonnable et que les draps sont propres."] = "44af32f368e03c09b89fe9f87be3875e",
            ["Où voulez-vous aller ?"] = "2402ec9453525b4ec16e1180457c7cfb",
            ["Quel Maître de profession cherchez-vous ?"] = "ce83ae92effc9c6509cef60c5f919389",
            ["Quel champ de bataille vous intéresse ?"] = "481f209702cc74fc87fe4569d25b276b",
            ["Quel maître de classe recherchez-vous ?"] = "7e357056bac5b73342ac2bee0458e300",
            ["Rien de tel que de passer une journée à pêcher au lac de Cristal. Arnold Leland est l’homme qui m’a instruit. Il se trouve habituellement sur les docks dans le Quartier du Canal en train de pêcher à longueur de journée.   Oh, et ne croyez pas une seule des histoires qu’il pourra vous raconter à propos des monstres dans les canaux."] = "852f678dbc06d3601bdf168e7032735a",
            ["Rien ne vaut la communion avec la nature. C'est ce que disent les elfes en tout cas. Ce n'est pas trop mon truc de parler aux fleurs et aux arbres, mais Tannysa pourra sans doute vous aider. Elle est dans le quartier des Mages, non loin de la boutique 'Tout pour l'alchimiste'."] = "42747362bb8e6d2164d7e79747248058",
            ["Si vous avez besoin d'abriter votre familier pendant que vous en formez un autre, parlez à Jenova Stoneshield, dans le quartier des nains."] = "b68ea919378ae726f910e862a386d16f",
            ["Si vous avez besoin d’entraînement en matière d’alchimie, il n’y a qu’un seul endroit à Stormwind où vous devez vous rendre : 'Tout pour l'alchimiste'. Vous pourrez trouver cet endroit dans le quartier des mages, aux abords des boutiques."] = "7034523efe4bfc8203b790a1d127dca2",
            ["Si vous cherchez à devenir un grand cuisinier, risquez-vous à pousser la porte de la Taverne du Cochon siffleur et parlez à Stephen Ryback. Cet homme sait comment cuisiner des côtes comme personne.  Mince alors... vous m’avez donné faim de ses fameuses côtes. Cependant, ne comptez pas sur lui pour vous enseigner cette recette !"] = "dbe19e29f297c8e1fb35a95e50f89466",
            ["Si vous cherchez à devenir un puissant paladin, vous ne trouverez pas meilleur professeur que le seigneur Grayson Shadowbreaker. Il se trouve dans la Cathédrale de la Lumière, au cœur de la place de la Cathédrale."] = "2d22a7afddcc8d88b9c1353ae28daf09",
            ["Therum Deepforge est le nain avec qui vous devez vous entretenir. Si vous voulez savoir, il s’agit d’un des meilleurs forgerons des alentours. Vous pouvez le trouver au cœur du quartier des nains."] = "a4956fb4f50c46eaea4f68dd50ceb194",
            ["Thorfin Stoneshield est venu nous voir depuis Ironforge pour nous offrir ses connaissances de la chasse. Si l'air enfumé du quartier des nains ne vous dérange pas, vous le trouverez dans sa maison du nord-est."] = "8c8ac67be8a32d83d11e1119cbe8b9f8",
            ["Un autre entrepeneur, hein ? Eh bien, l’hôtel des ventes se trouve dans le Quartier commerçant, pas très loin de la banque."] = "3b18fc0710278c6aa12fb30a85999aaf",
            ["Un chasseur, hein ? Alors c'est à Thorfin Stoneshield que vous devez parler, dans le quartier des nains.  Oh, et n'oubliez pas de lui dire que si sa bestiole continue à salir les trottoirs, il devra bientôt former les chasseurs derrière les barreaux de la Prison !"] = "d9d6fc265ce7e558402d3ca53747dac5",
            ["Un grand cuisinier travaille à la taverne du Cochon siffleur, dans la Vieille ville. Je l'ai vu utiliser un couteau devant ses fourneaux, et, entre nous, je ne crois pas qu'il n'ait fait que des omelettes dans sa vie. Cela dit, si vous voulez apprendre l'art culinaire, c'est le meilleur."] = "af66b0b5d2d42f34571240ac0c887807",
            ["Un tailleur ? Ma foi, si vous restez ici assez longtemps, vous finirez par entendre parler de Georgio Bolero. Ça fait des mois qu'il oriente la mode ici. Si vous voulez apprendre quelque chose de lui, vous le trouverez dans le quartier des mages, dans le cercle extérieur."] = "9cba4dc5407b5b21f860b325ab149a86",
            ["Vous aimez le cuir, hein ? Alors vous devez parler à Simon Tanner, dans la vieille ville. Il y tient une boutique qui s'appelle Au cuir protecteur."] = "02b8fd48e20c73453938adc9f4995c2c",
            ["Vous allez devoir vous diriger vers la Vieille ville et faire un saut au Cuir protecteur si vous souhaitez apprendre l’art du dépeçage."] = "6f55eb7e6eebe144bc957790dae41464",
            ["Vous allez former une guilde, n’est-ce pas ? Bonne chance à vous alors !  Entretenez-vous avec Aldwin Laughlin au Centre d’accueil des visiteurs de Stormwind. Il se trouve dans le Quartier commerçant, sur votre droite lorsque vous arrivez de la Vallée des Héros."] = "dbd178f951b41e05c59af921ec3b7725",
            ["Vous avez entendu parler du tram, non ? C'est quelque chose de fabuleux ! Vous le trouverez dans le quartier des nains, au fond. Oh, et ne sortez pas vos bras ou vos jambes quand il se déplace."] = "98484e0cd95c72af21e16247f3eead70",
            ["Vous cherchez un entraînement ? Je pourrais vous entraîner mieux que quiconque à Stormwind mais la garde l’interdit. Je suppose que vous allez devoir vous contenter d'un de ces ratés qui traînent autour de la Caserne ou à la Taverne dans la vieille ville."] = "cd7fa3fdce25e94d80b36771810f1e93",
            ["Vous cherchez à faire un tour en gryphon, hein ? Dungar garde ses oiseaux là-haut sur le rempart dans le Quartier commerçant. Rappelez-vous seulement de bien vous accrocher !"] = "7df84a254c23565acaa7fc468ead3ab2",
            ["Vous devez parler à Osborne, alors. Il n’existe pas de Maître du Camouflage plus doué que lui à Stormwind. Partez à sa recherche en parcourant la vieille ville."] = "5079ccedcf83df1e6554116dbaa337bd",
            ["Vous n'avez pas assez de cran pour monter à dos de gryphon, hein ? C'est une chance, on a quelque chose qui vous permettrait de rester sur le plancher des kodos. C'est le transport en commun des gnomes, le Tram des profondeurs. Il est situé au fond du quartier des nains."] = "b8a17986e4d6330f2e74f8f8a53c0d86",
            ["Vous ne sentez pas la fumée des forges naines ? Ma foi, c'est Therum Deepforge que vous devez trouver si vous voulez progresser comme forgeron. Il est dans le quartier des nains, juste au nord de la place de la Cathédrale."] = "a3a18a74f32a8ebab3109103db8d0fd5",
            ["Vous pourrez trouver Tannysa devant le magasin d'alchimie, dans le quartier des Mages."] = "356b1700581f2c27333ab266a26bb077",
            ["Vous pourrez trouver Theridan ou Maldryn à proximité du puits de lune dans le Parc. Allez à la zone ouest de Stormwind, au nord du quartier des mages, mais à l'ouest de la place de la Cathédrale."] = "2c1e9110dff51f5d1d491b13523c5989",
            ["Vous pourrez trouver le Maître des gryphons sur le rempart nord-est dominant la Vallée des Héros."] = "f5c1db946eb2f4fba13e922275d9fb95",
            ["Vous pouvez trouver Aldwin Laughlin au Centre d’accueil des visiteurs de Stormwind dans le Quartier commerçant."] = "53cfbdba892d116c2e03388c9fd6d5d0",
            ["Vous savez, je pourrais découper comme un rien un orc ou un troll. Je pourrais même graver mes initiales sur les flancs d'un ogre. Mais dépecer un animal, je ne peux pas. Allez comprendre.   Enfin, si vous avez assez d'estomac pour ça, allez voir Maris Granger au Cuir protecteur, dans la vieille ville."] = "c7ce82c152a63bc669f1d309ce17f9bd",
            ["Vous trouverez dame Hoteshem dans la salle d’audience du roi. Elle vous aidera à vous rendre au bassin d’Arathi, où la Ligue d’Arathor a besoin d’aide contre les Profanateurs."] = "9ff1ef7f7918452a7571c3f770ab4e14",
        },
        [197] = {
            ["Hé ! Vous m'avez l'air d'être costaud. Nous autres gardes sommes en sous-effectif. Vous pourriez nous aider..."] = "2343fa9b01b2ca00b5bc7a390ac07935",
        },
        [198] = {
            ["Salutation, mage. Puis-je vous offrir une nouvelle vision du monde de la magie ?"] = "3ddc082eac22c52bb34743331a694904",
            ["Salutations, $c. Permettez-moi de vous donner un conseil. Lors de vos voyages, prenez garde à la magie, car elle brûle les non-initiés."] = "54074b0b08d3a499512ae6fba95f3115",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
        },
        [223] = {
            ["Lorsque j'ai réussi à m'extraire de ma tombe, je pensais que ma famille m'accueillerait à bras ouverts. Mais ils m'ont chassé du village, hurlant dans une langue que je ne comprenais plus."] = "94095eb43627763b471b3b24bdf02a82",
        },
        [233] = {
            ["Les temps sont durs, hein, $N ? Où qu'on regarde, quelqu'un a besoin d'aide. Ma femme et moi aussi."] = "9331c7d44a0e3e3352a08f93cde78162",
        },
        [234] = {
            ["Une corruption immonde s'est infiltrée dans Westfall.  Alors que je faisais mon devoir sur les champs de bataille de Lordaeron, ces fermes honnêtes ont été envahies et transformées en repaires pour les voyous et les assassins. La Milice populaire a besoin de votre aide."] = "bf0787ecbd6400134f7c68d96b745095",
        },
        [235] = {
            ["Bienvenue dans notre humble demeure !  C'est toujours agréable de voir un visage amical.  Et vous avez des bras très forts.  Mon mari et moi sommes toujours à la recherche d'aide à la ferme.  Maintenant que la plupart des bonnes gens sont partis, il est difficile de trouver une personne capable de nous aider."] = "33f04ffc986b09b85415770b3eb442ec",
        },
        [237] = {
            ["Il n'y a que des problèmes dans ces régions.  J'ai essayé de dire à cet imbécile de Saldean de partir tant qu'il le pouvait, mais il ne veut pas en entendre parler.  Mais je ne suis pas dupe.  Verna et moi allons partir dès que nous aurons réparé ce chariot."] = "3a1ef61e65fa4ac456d8266c27986f6b",
        },
        [238] = {
            ["Parfois, j'ai l'impression qu'il y a un gros nuage gris dans le ciel, qui fait pleuvoir la malchance sur nous.  D'abord, nous sommes chassés de nos terres, et maintenant nous ne pouvons même pas sortir de Westfall.  Tout est en désordre.  Il faut faire quelque chose."] = "3db41f8f035f725c55ecc861457ca5c4",
        },
        [239] = {
            ["Aventure dans des pays lointains et proches$BRencontrer des gens bizarres et étranges$BMais si vous me posez une question$BVous devez d'abord accomplir une tâche simple !"] = "a1d52eb492cdf995ec86b759ea732fcb",
        },
        [240] = {
            ["Ha, c'est déjà pas facile de maintenir l'ordre par ici sans rajouter tous ces nouveaux problèmes ! J'espère que vous apportez de bonnes nouvelles, $n..."] = "0e27e4d990918879c04d6c20fbce449c",
        },
        [241] = {
            ["Salut, mon ami.  Je m'appelle Remy.  Je viens de Redridge, à l'est, et je suis venu ici pour faire des affaires, pour faire des affaires.  Vous en avez... vous en avez ? ?"] = "f8036e7c439c0eb3a26dfc62ac1aa55b",
        },
        [253] = {
            ["Aha ! Bonjour, bonjour, Maître $C !  Venez, asseyez-vous et buvez un verre.  Vous avez l'air entreprenant, et je pense que vous trouverez que me parler vaut la peine..."] = "95569555dc7eef49b2017ae3cc8293bf",
        },
        [261] = {
            ["Bonjour, citoyenne.  Vous avez l'air d'une $g homme:femme; avec un but - avez-vous des affaires avec l'armée de Stormwind ?"] = "8258324df960cc7895aa7a47061066c2",
        },
        [264] = {
            ["Repos, $C.  Si vous ne faites que passer, je vous suggère de vous en tenir aux routes et de ne voyager que de jour. Si votre activité se déroule dans le Darkshire, pensez à mettre vos compétences au service de la Garde de nuit.  Nos compétences sont incontestables, mais nous sommes peu nombreux."] = "fbd9667fbb9137567adcccc4c43bed10",
        },
        [265] = {
            ["J'ai senti ta venue depuis un certain temps, $n.  C'était écrit dans le motif des étoiles."] = "337e6a87fdbc0c0c10c32e2618e1d78e",
        },
        [267] = {
            ["Bienvenue dans la ville de Darkshire.  Le greffier Daltry est à votre service.  Puis-je vous aider ?"] = "d61bc8d45a3d7848d3f2554737fea5fb",
        },
        [272] = {
            ["Bonjour, bonjour !  Bienvenue dans ma cuisine, $g monsieur:dame; !  C'est ici que sont préparés les meilleurs plats de la Taverne du Corbeau écarlate.  Ah, sentez ce merveilleux arôme !"] = "8d1d7ec8e88045e7ac9d23a49fb86f88",
        },
        [273] = {
            ["Gardez la porte fermée, $C.  On ne sait jamais quand les Dark Riders repasseront par là."] = "8682df03cf89f55d63077ee4506fd321",
        },
        [277] = {
            ["La meilleure affaire de Stormwind, mon $g ami:amie;, je vous le dis. Vous ne trouverez rien de meilleur. En quoi puis-je vous être utile ?"] = "0a50227fd4a79a221c5e74147031f06e",
            ["La meilleure affaire de Stormwind, mon $gami:amie;, je vous le dis. Vous ne trouverez rien de meilleur. En quoi puis-je vous être utile ?"] = "0a50227fd4a79a221c5e74147031f06e",
            ["Vous vouliez juste regarder ou y a-t-il quelque chose de précis que vous cherchez ?"] = "a86de99ac7614f683ab7eab24b0a0b93",
        },
        [278] = {
            ["Bonjour, bonne $g monsieur:dame;.  Asseyez-vous, et mangez si vous avez faim.  Ne vous inquiétez pas si j'ai l'air occupé par mes travaux d'aiguille - je vous écoute..."] = "d5cd1c951f980789421f43fefe1f5cab",
        },
        [288] = {
            ["Huh ?!?  Oh.  Vous n'avez pas l'air d'un voleur Defias... ou d'un membre de la Garde de Nuit.  Ayez pitié d'une pauvre âme, voulez-vous ?"] = "7321affec8a5c22b6e0c288786215509",
        },
        [289] = {
            ["Eh ?  Salutations, jeune $C.  Tu es bien courageux de trouver ton chemin ici avec toutes ces créatures errantes !$B$BMaintenant que tu es là, tu peux peut-être aider un vieil ermite..."] = "1c989cbbea7043dfca09623b015dedf0",
        },
        [294] = {
            ["Salut au voyageur.  J'ai beau avoir une mauvaise vue, je peux sentir les pas d'un $c à un kilomètre de distance.  Pendant des années, j'ai défendu Stormwind avec fierté, mais lorsque mes yeux m'ont lâché, j'ai été contraint de me retirer."] = "f3ecdc31f36a23fd5f5e7b95c267cc89",
        },
        [295] = {
            ["Bienvenue dans mon auberge, $gvoyageur épuisé:voyageuse épuisée;. Que puis-je faire pour vous ?"] = "e3e01e02de026cbe5e2560a468bbdebb",
            ["Les gages d’amour sont de petits messages d’affection que vous pouvez donner aux habitants des villes et des capitales qui ont le cœur à l’amour. En échange, elles vous offriront un cadeau d’adoration.$B$BSi vous êtes déjà $gadoré:adorée; par quelqu’un d’autre, elles vous remettront au moins un cadeau d’amitié."] = "d268a407b36e89a7c70ab981fb46abd7",
            ["Moi non, mais beaucoup de gens cherchent l’amour. Vous devriez mettre un peu de parfum ou d’eau de Cologne, acheter mes gages d’amour, et les faire circuler !"] = "137f53b5268a04b1b5bdb21820557b14",
            ["Qu'est-ce que vous pouvez faire dans une auberge ?$B$BEh bien, vous pouvez vous reposer confortablement. Et à grâce à cela, vous serez 'bien $greposé:reposée ;', plus rapidement que si vous étiez dehors. Et quand vous êtes bien $greposé:reposée;, vous profitez plus de votre expérience.$B$BVous pouvez aussi parler avec l'aubergiste pour obtenir une Pierre de foyer, afin de pouvoir revenir plus rapidement dans cette auberge."] = "8fc274a3d994a2459bdce3fd3dc98705",
            ["Quand vous donnez des gages d'amour aux habitants des villes, vous recevez différents cadeaux en retour. Vous pouvez en garder ou en utiliser certains, mais vous pouvez aussi en faire des assortiments que vous donnerez à votre héros préféré !$B$BAllez voir Kalin Colportecoeur pour donner vos cadeaux.$B$BVous pourrez trouver Kalin près de Bolvar, Magni et Tyrande."] = "fa856e726cbf60331453148913410f70",
            ["Quand vous donnez des gages d'amour aux habitants des villes, vous recevez différents cadeaux en retour. Vous pouvez en garder ou en utiliser certains, mais vous pouvez aussi en faire des assortiments que vous donnerez à votre héros préféré !$B$BAllez voir Kalin Colportecoeur pour donner vos cadeaux.$B$BVous pourrez trouver Kalin près de Cairne, Sylvanas et Thrall."] = "616aaf989a9683312fafbb75a48fe26b",
            ["Si vous mettez de l’eau de Cologne ou du parfum, vous verrez qui a le cœur à l’amour. Tous acceptent les gages d’amour… et vous offrent un don en échange.$B$BAttention, pour donner un gage d’amour à quelqu’un, vous devez avoir la bonne odeur. Les hommes aiment l’odeur du parfum, et les femmes celles de l’eau de Cologne."] = "206f059d0c629c5d37a5efc62769a4a3",
        },
        [313] = {
            ["Bienvenue dans la Tour d'Azora, jeune $C.  Je suis Théocrite.$B$BAvez-vous affaire à moi ?  Ou... ai-je affaire à vous, peut-être ?"] = "6182da5b074eb25d24dd29a333868e22",
        },
        [328] = {
            ["Salutation, mage. Puis-je vous offrir une nouvelle vision du monde de la magie ?"] = "3ddc082eac22c52bb34743331a694904",
            ["Salutations, $c. Permettez-moi de vous donner un conseil. Lors de vos voyages, prenez garde à la magie, car elle brûle les non-initiés."] = "54074b0b08d3a499512ae6fba95f3115",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
        },
        [331] = {
            ["Salutation, mage. Puis-je vous offrir une nouvelle vision du monde de la magie ?"] = "3ddc082eac22c52bb34743331a694904",
            ["Salutations, $c. Permettez-moi de vous donner un conseil. Lors de vos voyages, prenez garde à la magie, car elle brûle les non-initiés."] = "54074b0b08d3a499512ae6fba95f3115",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
        },
        [332] = {
            ["Bienvenue au QG du SI:7, $n."] = "f02518f56be86de855c4a5c585841f34",
        },
        [341] = {
            ["Je n'ai pas beaucoup de temps pour les discussions oiseuses, $N.  Je dois reconstruire ce pont avant que la pluie n'arrive.  J'ai terminé tous les projets en respectant les délais et le budget et je n'ai pas l'intention de commencer à déraper maintenant."] = "46e52b54b40320d1794923d450a74c44",
        },
        [342] = {
            ["Salut, $N !  Bienvenue dans mon humble jardin.  Le temps a été parfait ces derniers temps.  Espérons qu'il se maintienne pour que la récolte soit mûre."] = "06c875e93cfe3fa732719481017369a8",
        },
        [344] = {
            ["Qui est ce $c qui se présente devant la Cour du Lakshire dans le Royaume de Stormwind ?  Expliquez-nous ce que vous avez à faire dans ce canton, $R.  La menace orque qui pèse sur le royaume est bien trop grande pour que nous perdions du temps en conversations oiseuses."] = "46d0e4b19c3e1bf929fc184bef2f54a1",
        },
        [347] = {
            ["Je suis désolé, $c, mais il vous faut davantage d'expérience pour survivre dans la vallée d'Alterac."] = "b83ab9c1a9dd85b93121a8a221e21094",
            ["La garde Stormpike doit être détruite ! Prêt pour la vallée d’Alterac, $c ?"] = "81ed3ff7e3aa4663fea43677ac077dd8",
        },
        [352] = {
            ["Ces superbes bêtes empruntent des voies qui sont inaccessibles à pied. Vous arriverez plus rapidement à destination et vous verrez des choses que vous n'auriez pas vues du sol."] = "483ae8ef81d9a1fa5470403f505b2d87",
            ["Où que c'est qu'vous voulez aller, $gl'ami:l'amie; ? Pour quelques pièces, mes gryphons peuvent vous faire une monture plus rapide qu'le plus rapide des canassons !"] = "6b05ee484d45803ee175e05a07d644f4",
        },
        [375] = {
            ["La Lumière est avec vous, $N. Puis-je vous aider en quoi que ce soit ?"] = "aebf3948f2b6eeebadd9d114b8e08bba",
            ["Ne tournez pas le dos à la Lumière, $c, c'est peut-être ce qui vous sauvera un jour."] = "120875f188ac12780f811009b51a783b",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "768f0928588ebe52253715a9f6b21ad7",
        },
        [376] = {
            ["La Lumière est avec vous, $N. Puis-je vous aider en quoi que ce soit ?"] = "aebf3948f2b6eeebadd9d114b8e08bba",
            ["Ne tournez pas le dos à la Lumière, $c, c'est peut-être ce qui vous sauvera un jour."] = "120875f188ac12780f811009b51a783b",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "768f0928588ebe52253715a9f6b21ad7",
        },
        [377] = {
            ["La Lumière est avec vous, $N. Puis-je vous aider en quoi que ce soit ?"] = "aebf3948f2b6eeebadd9d114b8e08bba",
            ["Ne tournez pas le dos à la Lumière, $c, c'est peut-être ce qui vous sauvera un jour."] = "120875f188ac12780f811009b51a783b",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "768f0928588ebe52253715a9f6b21ad7",
        },
        [381] = {
            ["Bien vu, $C.  Si vous êtes ici pour affaires, allez vous chercher une bière et nous discuterons."] = "ddc30f62024a13c934f03e207c662870",
        },
        [382] = {
            ["Je n'ai pas le temps de bavarder, citoyen, mais si tu es prêt à nous aider contre les orcs, je te trouverai une utilité."] = "3c180db27e28d7858ec6ae858d96ec0f",
        },
        [384] = {
            ["Ah non, je ne désire pas vendre de cheval à quelqu'un qui n'est pas considéré au moins comme exalté par le royaume de Stormwind. Ces montures sont les meilleures que vous trouverez, nous ne voulons pas qu'ils finissent entre les mains de l'ennemi.$B$BJe ne dis pas que vous êtes hostile, bien sûr... Mais gagnez la confiance de Stormwind et nous pourrons parler affaires."] = "33c0e9087e12555f8dc52cc2a68cccb1",
            ["Ces chevaux sont le résultat des meilleures techniques de reproduction et d'une attention de tous les instants ! Prenez votre temps pour choisir votre monture. Un cheval, c'est un compagnon pour la vie. Il faut vous mettre en valeur. Achetez votre monture ici aujourd'hui même !"] = "0016d0ff7c43ada7e4f367d5b24e9b81",
        },
        [415] = {
            ["Hey $g copain:copine;, tu penses que tu pourrais me donner un coup de main ?  Je suis vraiment dans une situation difficile..."] = "cc055e12d3db6948a61792148d209f80",
        },
        [459] = {
            ["Les arcanes ne corrompent que les faibles. Même si vous ne suivez pas le chemin des démonistes, souvenez-vous-en."] = "bf6b174b1213cc9fc8478d3b5f2b4971",
            ["Les ténèbres vous rejettent, $c. Cessez de me casser les oreilles et sortez de ma vue. Disparaissez !"] = "2aabd37566ced1f9550e86910bb3baf8",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "768f0928588ebe52253715a9f6b21ad7",
        },
        [460] = {
            ["J'ai bien peur que votre quotient de ténèbres ne soit pas suffisant pour mériter que je discute plus longtemps avec vous. Passez votre chemin."] = "8045db4a1a25656b86eb87b955fbe642",
            ["Les arcanes ne corrompent que les faibles. Continuez de vous entraîner, ou vous subirez le même sort."] = "073492d1b775dad17b73e4495accc8b7",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "a9083a5c3e3237e00bd856dcc0fd400d",
        },
        [461] = {
            ["Les arcanes ne corrompent que les faibles. Continuez votre formation ou vous connaîtrez un sort similaire."] = "c381816693d5bcf8cf6644c3ad7a0dea",
            ["Les ténèbres vous rejettent, $c. Cessez de me casser les oreilles et sortez de ma vue. Disparaissez !"] = "2aabd37566ced1f9550e86910bb3baf8",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "768f0928588ebe52253715a9f6b21ad7",
        },
        [464] = {
            ["Salut, $C.  Les temps sont durs, mon ami, car notre ville est assiégée !  Les orques de Blackrock attaquent depuis le donjon de Stonewatch, les Shadowhides menacent la tour d'Ilgalar et la meute de gnolls de Redridge se renforce.  J'espère que vous n'êtes pas en vacances..."] = "6f87d92a661abe64c1fe3bdb763a0e8c",
        },
        [469] = {
            ["Bonjour, $c.  Si vous êtes un ami du colonel Kurzen, je vous ferai abattre là où vous êtes ! Mais si vous êtes venu nous aider, prêtez l'oreille..."] = "8cd6e7deb04827e4aff4f203914eeace",
        },
        [483] = {
            ["La meilleure affaire de Stormwind, mon $g ami:amie;, je vous le dis. Vous ne trouverez rien de meilleur. En quoi puis-je vous être utile ?"] = "930e45368ed7dcac8e799df8fa5bc730",
            ["La meilleure affaire de Stormwind, mon $gami:amie;, je vous le dis. Vous ne trouverez rien de meilleur. En quoi puis-je vous être utile ?"] = "930e45368ed7dcac8e799df8fa5bc730",
            ["Vous vouliez juste regarder ou y a-t-il quelque chose de précis que vous cherchez ?"] = "b27e9e38daaae8b0ac9e5d7775fe5a70",
        },
        [491] = {
            ["J'essaie d'avoir toujours des stocks à la colline des Sentinelles, mais ce n'est pas facile vu ce qui se passe en ce moment."] = "f25d9eb86b1a32dfb1649beab901ef4c",
        },
        [514] = {
            ["Je n'ai guère de temps pour le moment, je fais des fers à cheval pour Verner Osgood de Lakeshire."] = "80c8a703f2783e988393cdc3f26954dd",
        },
        [523] = {
            ["Où allez-vous ? Si vous voulez aller là-bas rapidement, alors ne cherchez pas plus loin !"] = "a8c3fee28c1869e9b77707e11b8cd0a2",
        },
        [543] = {
            ["Ah ! Je n'aide que les chasseurs et leurs familiers."] = "4c9a93178a8bd81be46f856336284914",
            ["Vous êtes là pour une formation qui vous permettrait de fortifier vos familiers ?"] = "89218c24a0eff1fa5c10022467769ef7",
        },
        [633] = {
            ["Les temps sont sombres, $c... Bientôt, nous perdrons tout... Quand la lumière abandonnera tout le monde sauf ceux qui marchent vraiment sous la lumière."] = "93332ee7844ac28745ab9d0a9255f21e",
        },
        [656] = {
            ["Il y avait des voleurs partout !$B$BC'était horrible.  La grotte nous est tombée dessus.  Je crois que toute la compagnie minière est morte, y compris mon frère, le contremaître."] = "f3182ac7e91407ee4bc95164619c9f08",
        },
        [658] = {
            ["Ah, c'est que vous m'avez l'air solide ! Vous pourrez peut-être m'aider pour un détail ou deux. Je ne trouve guère d'aide ici, sauf auprès d'apprentis sans expérience, et ils ont d'autres chats à fouetter."] = "5fc097432cec6da6622815d859a41a7a",
        },
        [661] = {
            ["Salutations. Que faites-vous avec la famille Carevin ? Cherchez-vous à aider les Carevins dans leur lutte contre les morts-vivants ?"] = "021f194b990d2f773bafd579b1aa4e70",
        },
        [663] = {
            ["La famille Carevin se bat pour la victoire sous la Lumière. Mon devoir sous la Lumière est de donner ma vie dans leur combat contre les morts-vivants. Maître Carevin m'a chargé d'exterminer les vils worgens de Duskwood. Peut-être pourriez-vous m'aider ?"] = "156025502b69aa6671e92d41cf6d601c",
        },
        [714] = {
            ["Bonjour, $c ! Belle journée pour la chasse, n'est-ce pas ? J'ai moi-même eu de la chance avec les sangliers. Peut-être aimeriez-vous essayer ?"] = "51372d66d806ff4cb6ab1b26eba30eb3",
        },
        [715] = {
            ["Encore une belle journée dans la jungle !  Ça va être une sacrée chasse, je le sens.  Une fois que Barnil aura nettoyé les fusils, j'emmènerai le groupe de chasseurs au plus profond des lianes tortueuses.  Ce n'est pas une mauvaise façon pour un ancien combattant de passer sa retraite, n'est-ce pas ?"] = "b4f3331c89b3d2062ca281510ee317ad",
        },
        [716] = {
            ["Une grande chasse attend maître Nesingwary. Je trouve que le préparer pour une journée dans la jungle est beaucoup moins stressant que de l'aider à se préparer au combat. Malgré tout, ces moments glorieux sur le champ de bataille me manquent."] = "e3a348a35882a9d1e3d9c86ff56b6bbe",
        },
        [727] = {
            ["Ah ! Ça, c'est parlé ! Je parie que Granis Swiftaxe pourrait vous apprendre une chose ou deux sur la manière de faire tournoyer l'acier. Il est à la Distillerie Thunderbrew de Kharanos à cette heure."] = "0fd2049ea24b3dbd43761a96e891bd61",
            ["Ah, Stonebrow ne quitte pas beaucoup Ironforge ces temps-ci. Si vous voulez devenir tailleur, c'est lui qu'il faut aller voir à Ironforge."] = "63ec46e6d95ea9bc754d4ccb65dd8202",
            ["Allez donc à Ironforge si vous voulez en apprendre plus sur les enchantements. Je crois y avoir vu une échoppe près du Maître des gryphons la dernière fois que j'y suis allé."] = "e56f9fe4500923af12e19f791a883d14",
            ["Ce Granis Swiftaxe pourrait boire à en rouler sous la table et néanmoins manier sa hache avec habileté. Si vous cherchez de l'entraînement, essayez quand même de lui parler tant qu'il est compréhensible."] = "ee5ecc14e2bf49a6990e74cae4288e7b",
            ["Ce genre de magie n'apporte que des ennuis, je vous le dis ! Je ne sais pas pourquoi ce Grimrizz a été autorisé à s'installer à la sortie de la Distillerie Thunderbrew ! Ne vous en approchez pas !"] = "f1180972db6665288081c1cfc7b5f408",
            ["Ce vieux Thamner m'a bandé, l'autre jour, quand j'ai échappé de justesse à un mauvais trogg. Je suis comme neuf, je vous le dis ! J'ai la conviction que Thamner sera enchanté de vous apprendre à faire de bons bandages."] = "93839b8ccc68c7af9e06e65b17c1fd90",
            ["Cherchez donc Bronk au Dépôt de Steelgrill. Quand il ne bricole pas quelque machin bizarre, il discute généralement avec les pilotes sur leurs chars à vapeur."] = "f4fbd7429c935511c5657b11b95d1303",
            ["Croyez-moi, depuis qu'il fait ce métier, Bronk a toutes les vis ! Mais personne n'est meilleur ingénieur que lui. Allez donc lui rendre une petite visite au Dépôt de Steelgrill."] = "d505dd7c90c149052d96dc5021198f21",
            ["Eh bien, vous trouverez Shelby Stoneflint à la sortie de la Distillerie Thunderbrew, dans Kharanos. Elle s'occupera bien de tous les familiers que vous pouvez avoir."] = "bee5611eb524aaf54dfb7c803d87d4c9",
            ["Gremlock n'est pas toujours bien chanceux en cuisine, mais il a de bonnes recettes qui méritent d'être apprises. Allez lui parler à la Distillerie Thunderbrew et voyez ce qu'il peut vous enseigner."] = "812ca9ddb549b5088d51719a6d51434b",
            ["Il n'y a pas beaucoup de bons coins de pêche dans les environs. Paxton les connaît tous et il y en a sans doute dont il ne vous parlera pas. Allez donc au Lac glacial et voyez ce qu'il vous dira."] = "8bbfc8f6de8eca0089d8559839569436",
            ["Il n'y a pas de dépeceurs à Dun Morogh $gmon garçon : ma petite;, ils sont presque tous à Ironforge si c'est un apprentissage qui vous intéresse."] = "6a6954aa23ff423b51b954fe09b144a8",
            ["Il paraît qu'il y a une échoppe à Ironforge, tenue par des gnomes, spécialisée dans l'alchimie. Allez y jeter un coup d'oeil."] = "e59e7a5d5007c14bc99785f8ce315a5c",
            ["Il y a un mage à la Distillerie Thunderbrew qui pourrait vous apprendre quelques nouveaux sorts. Je crois que son nom est Magis Sparkmantle."] = "cfa572bac748ea1fa7e7c25dc2a4ae04",
            ["Ironforge est le meilleur endroit pour se perfectionner en travail du cuir. Si je me souviens bien, il y a une échoppe du côté de la Grande Forge où vous trouverez votre bonheur."] = "712130efaf95afb9ccb5f2a5c069c0fc",
            ["La banque la plus proche est le Coffre d'Ironforge, $gjeune homme : jeune fille;."] = "501c83ee292da27782fae1e60bf7c3f3",
            ["Le Coffre d'Ironforge est la banque la plus proche de la région."] = "83965dbeffe98cceda0d3e3dbf0734c2",
            ["Le Maître des gryphons le plus proche se trouve à Ironforge, près de la Grande Forge elle-même. Vous devez vous diriger vers Ironforge si vous souhaitez voyager en gryphon."] = "c32efb4b50768d9afd75e50dc0393a88",
            ["Les Thunderbrew dirigent une excellente auberge à Kharanos, elle porte leur nom. Prenez-y une bonne pinte et dormez un peu."] = "0ee12bb81d2947b566609b7ba822b401",
            ["Les démonistes... C'est pas mon truc. Comme ce Grimrizz qui a monté son échoppe à la sortie de la Distillerie Thunderbrew. La bière va sans doute devenir amère à cause de lui ! Les démonistes... Bah !"] = "60bf6744b34a4b35ea7e3f938b4de2fd",
            ["Les dépeceurs apportent généralement leurs peaux à Ironforge pour les y faire sécher. Vous devriez vous y rendre et voir qui peut vous entraîner !"] = "12bf423a5f31db52e9d292ceb06ece6b",
            ["Les premiers soins, ça ne vaut peut-être pas les secours prodigués par les prêtres, mais c'est quand même utile. Allez donc parler à Thamner dans la Distillerie Thunderbrew, il pourra sans doute vous enseigner bien des choses."] = "a88b941bc8e164b364a0b5d642a579b5",
            ["Ma foi, il semble que nous cherchions tous deux Hogral Bakkan. C'est un nain, pas de doute, à un moment ou à une autre vous le trouverez donc à la Distillerie Thunderbrew, à la recherche d'une bière. Il y est peut-être en ce moment même."] = "1f4384179f7f2eff7cf1e505f549b91e",
            ["Ma foi, vous avez peu de chances de trouver un tailleur ici. Ironforge en abrite quelques-uns, en revanche. Allez-y et demandez de l'aide à un garde."] = "720fafcfb6472426d4149a74769fda89",
            ["Non, pas d'alchimistes ici, à Dun Morogh. Vous les trouverez à Ironforge... Essayez les gnomes de Brikabrok."] = "f7cf19aeccddff42a9a0b22c505718cc",
            ["Non, personne ne peut vous apprendre l'herboristerie ici. Je pense que vous y arriverez mieux à Ironforge."] = "5aaf2f083eef745315ab1a2dc692fcb0",
            ["Och ! Ça, c'est une compétence digne de ce nom ! Tognus utilise l'enclume comme personne. Allez donc lui parler et voyez ce qu'il peut vous enseigner."] = "5240f70aad5a8e58147ce8fae9c1ec57",
            ["Och... Un paladin ? Eh bien, $gmon garçon : ma fille;, vous avez de la chance ! Azar Stronghammer est de retour de son entraînement et se trouve actuellement à la Distillerie Thunderbrew, dans Kharanos."] = "9d8f2dd4c4db277f02b3c5d5f15c9354",
            ["Oh, un prêtre, vraiment ? Eh bien, le vieux Maxan est à coup sûr en train de boire un verre dans la Distillerie Thunderbrew, si vous avez besoin de leçons."] = "9a7b6a50e57d38d1acb4f3bff531e0f2",
            ["On ne peut guère pêcher par ici, mais si quelqu'un y peut quelque chose, c'est bien Paxton ! Vous le trouverez en train de pêcher au bord du Lac glacial."] = "467b47eb9a3d4006f250fad9ecb18eb0",
            ["Oooh, une auberge, hein ? Y a rien de mieux que la Distillerie Thunderbrew. Reposez-vous si c'est nécessaire, mais surtout, buvez-y une bière ou deux."] = "e66a69d239e7c3f1206d7f638c44bec1",
            ["Où voulez-vous aller ?"] = "411e9efc17c0fa67fa3a65ddbceb693f",
            ["Pour autant que je sache, il n'y a pas d'enchanteurs dans Dun Morogh. Il va falloir aller à Ironforge si vous voulez apprendre la profession d'enchanteur."] = "ccffed48b48def2c22f1c44f31434020",
            ["Quel Maître de classe cherchez-vous ?"] = "dcadd0f33e63218ef70a191c145117f6",
            ["Quel maître cherchez-vous ?"] = "cf38911600ac02c04cb72aafa6596e66",
            ["Quel maître de classe cherchez-vous ?"] = "dcadd0f33e63218ef70a191c145117f6",
            ["Quelle surprise de voir de petites fleurs pousser même sous le rude climat de Dun Morogh... Mais vous ne trouverez pas d'herboristes par ici. Il vous faudra aller à Ironforge pour vous former à ce métier."] = "3fd9a5ca3019eefa0d287e45aeacd7da",
            ["S'il y a un Maître des chasseurs à qui parler ici, c'est bien Grif Wildheart. Vous le trouverez à l'extérieur de la forge, dans Kharanos."] = "3043df25383951a157419bf109bd7229",
            ["Shelby Stoneflint abrite bon nombre de familiers pour les chasseurs locaux. Vous la trouverez près de la Distillerie Thunderbrew, si vous avez besoin qu'on s'occupe d'un de vos compagnons."] = "5011b7376cf9fbdf9a91842132fba2e6",
            ["Si vous voulez apprendre à travailler le cuir, il va vous falloir aller à Ironforge. Il paraît qu'il y a une sympathique échoppe près de la Grande Forge où vous pourrez apprendre le métier."] = "5ca39ccf61fd158a1d527dc435d98222",
            ["Si vous voulez mettre la main sur des papiers de création de guilde, vous devrez aller à Ironforge et visiter le Centre des visiteurs d'Ironforge."] = "395a422b3eb1d579d18416f0b5ef4bff",
            ["Tous ces officiels sont à Ironforge. Allez voir le Centre des visiteurs d'Ironforge pour les papiers de création d'une guilde."] = "f9fd222716447c9fab43d7fdd2bdcab4",
            ["Un mineur ? Il suffit de demander où en trouver un ! Yarr, c'est lui que vous cherchez. Vous le trouverez au Dépôt de Steelgrill."] = "4ef02a6cde5565b37e151274512c0641",
            ["Une pinte de Thunderbrew et un petit plat de Gremlock, voilà un bon repas ! Cherchez le cuistot si vous voulez apprendre à cuisinier."] = "d280277830161709ce905baf4cb22615",
            ["Vous allez où ?"] = "411e9efc17c0fa67fa3a65ddbceb693f",
            ["Vous avez besoin d'entraînement ? Ma foi, Azar Stronghammer est toujours prêt à enseigner deux ou trois choses aux jeunes paladins. Cherchez-le à la Distillerie Thunderbrew."] = "63af3d038f4096f6bba167a9b297ef08",
            ["Vous cherchez Hogral ? Avez-vous été à la taverne ? Och ! Si vous cherchez un voleur, et un nain en plus, commencez par l'auberge ! Allez-y sans tarder."] = "d218e9d1194ff62a08601af71245f9b8",
            ["Vous entendez sans doute Tognus battre l'enclume quand vous êtes à Kharanos. Cela dit, si vous ne vous êtes pas lavé les oreilles depuis longtemps, allez jeter un coup d'oeil à la Forge."] = "9f64ea1b3225a2261a71922332f8c889",
            ["Vous ne pensiez pas trouver une ville sans mineur, n'est-ce pas ? Yarr se trouve généralement au Dépôt de Steelgrill, à l'extérieur de Kharanos."] = "1c9825e778eedca69936cc9dcbf549ef",
            ["Vous ne trouverez pas de Maître des gryphons où que ce soit à Dun Morogh, $gmon garçon : ma fille;. Vous devez vous rendre à Ironforge si vous voulez chevaucher une de ces bestioles."] = "f3c8a5a8b088f61349bd467d2e1e02b1",
            ["Vous trouverez sûrement Maxan Anvol en train de picoler à la Distillerie Thunderbrew. Pourquoi n'allez-vous pas prendre une pinte et voir s'il peut vous enseigner quelque chose ?"] = "f9ef4e04eea4de713fc61313fd8a4c8e",
            ["Vous êtes $gsûr:sûre; que vous ne voulez pas devenir guerrier ? Comme vous voulez, c'est votre peau après tout. Si vous voulez vraiment apprendre à remuer les doigts, parlez à Magis Sparkmantle dans la Distillerie Thunderbrew."] = "3361a9560236765dd4f9f954267bed44",
            ["À mon avis, Grif passe un peu trop de temps avec les animaux. Mais personne ne connaît la voie du chasseur mieux que lui. Cherchez-le à l'extérieur de la forge de Kharanos."] = "5d54f11c82628de5397e4af70d935d39",
        },
        [733] = {
            ["Fais attention où tu mets les pieds ici, $g garçon:fille;.  Tu ne fais peut-être pas partie de notre équipe, mais ça ne veut pas dire que je ne vais pas te donner un coup de canne si tu ne respectes pas les règles !"] = "cf242c1f5d7697c74496f6a96f4c60c9",
        },
        [737] = {
            ["Eh bien, bonjour. On dirait que vous n'êtes pas opposé à l'idée de vous faire un peu d'argent, hm ? Je le vois à votre regard. Je suis le Mogul Kebok, responsable des opérations en Azeroth, et si c'est la richesse que vous cherchez, je peux peut-être m'arranger."] = "bed5db7c19da9db7ec35938ca77ad72e",
        },
        [738] = {
            ["C'est un endroit dangereux, $n. Soyez $gprudent:prudente;."] = "a765bd81d4444d7fa3d03cdef9f00bd6",
        },
        [773] = {
            ["$C, hein ? Je suis Krazek, le secrétaire du baron Revilgaz. Je suis au courant de tout ce qui se passe dans cette jungle et au-delà. Cela vous intéresserait-il de connaître le prix du pétrole à Ratchet ? Non ? Vous cherchez du travail, peut-être ? Je peux vous aider."] = "c150ea005524d091535d34c6f2d129d2",
        },
        [786] = {
            ["Bonjour, $g garçon:fille;. Je suis Grelin Barbe Blanche. Je suis ici pour examiner la menace que représente le nombre croissant de trolls dans la vallée de Coldridge. Qu'ai-je trouvé ? C'est un peu troublant..."] = "df26604e6baae8d611472c0496eb53e6",
        },
        [823] = {
            ["Bonjour, $c.  Normalement, je devrais être en train de surveiller les habitants de Stormwind, mais beaucoup de gardes de Stormwind se battent dans d'autres pays.  Je suis donc là, adjoint et je propose des primes alors que je préférerais patrouiller..."] = "129bddbdb1b8a7ac83bfcd6455dc23b0",
        },
        [836] = {
            ["Je vends les meilleurs vêtements et costumes en cuir de ce côté de la vallée !"] = "0f7736dc9f16d7152dca3f99e5a42807",
        },
        [837] = {
            ["J'espère que la Lumière est avec vous, $N. En quoi puis-je vous aider ?"] = "238a7cdf16a7d258e1b3789d98c5e7fb",
            ["Que la Lumière vous protège, $c."] = "852369f0d2fbc11e555e75fe5a433853",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "31ab172e1a375db1c9157d594eb608d9",
        },
        [857] = {
            ["Le bassin d’Arathi était notre foyer, et avec votre aide, il le redeviendra ! Nous aiderez-vous, $c ?"] = "72c6e36686e172b92adf3e89a32b9bdf",
        },
        [895] = {
            ["J'peux pas vous aider. Trouvez-vous un maître de vot'classe, $c."] = "65ffa984c80ec793cab656acd848ac8c",
            ["Qu'est-ce que j'peux faire pour vous ?"] = "ff4c1db50d39977890db3fe889ea21ae",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "31ab172e1a375db1c9157d594eb608d9",
        },
        [900] = {
            ["Qu'est-ce qui vous amène devant le tribunal de Lakeshire et l'honorable magistrat Solomon ?"] = "ecbc88ee5ec39c09cc42260c9b80d412",
        },
        [906] = {
            ["Les arcanes ne corrompent que les faibles. Continuez de vous entraîner, ou vous subirez le même sort."] = "7533bf57cdb44c24f4dde1a0d3b1909a",
            ["Les arcanes ne corrompent que les faibles. Continuez votre formation ou vous connaîtrez un sort similaire."] = "7533bf57cdb44c24f4dde1a0d3b1909a",
            ["Les ténèbres vous rejettent, $c. Cessez de me casser les oreilles et sortez de ma vue. Disparaissez !"] = "c4bef13520e7f7e2f4078fbe96c02345",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
        },
        [907] = {
            ["Je regrette, $c, mais vous devez gagner en force avant que je vous permette d'entrer dans le bassin d'Arathi."] = "a88973a558029a639cb379b7365f229a",
            ["J’espère que vous êtes là pour nous aider à arracher le bassin d’Arathi aux Profanateurs. N’est-ce pas, $N ?"] = "9a848f97bc7e29cb25689795f0cb46c4",
        },
        [911] = {
            ["Rien qu'à votre posture, je peux dire que vous n'êtes pas un guerrier.  $B$BAllez plutôt vous livrer à quelque activité sans danger... Lire un livre, ce genre de choses..."] = "8493fe09c36205db0684a4321f2d5dcf",
            ["Stormwind est le pilier de la race humaine ; nous la défendrons ainsi que l'ont fait nos ancêtres : de notre volonté et avec des lames affûtées."] = "0a37426688f72de523d491b07d11f473",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
        },
        [912] = {
            ["Les grandes guerres ont beau être finies, il nous faut poursuivre notre entraînement !"] = "ce85977b0f1b155023ca49641a927acd",
            ["Vous n'êtes pas un guerrier... Le dernier $c que j'ai entraîné n'a même pas tenu une journée.$B$BRegardez-moi ça, encore $gun gros malin:une petite futée; qui se prend pour un guerrier... Ah !"] = "64a04066374cb355ff1adeae11f4ae82",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "31ab172e1a375db1c9157d594eb608d9",
        },
        [913] = {
            ["Rien qu'à votre posture, je peux dire que vous n'êtes pas un guerrier.  $B$BAllez plutôt vous livrer à quelque activité sans danger... Lire un livre, ce genre de choses..."] = "1d00acba5fef6b2efb8c4454e9935541",
            ["Stormwind est le pilier de la race humaine ; nous la défendrons ainsi que l'ont fait nos ancêtres : de notre volonté et avec des lames affûtées."] = "92efeb5a1bded9ddac09c94a148f02c4",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "768f0928588ebe52253715a9f6b21ad7",
        },
        [914] = {
            ["Rien qu'à votre posture, je peux dire que vous n'êtes pas un guerrier.  $B$BAllez plutôt vous livrer à quelque activité sans danger... Lire un livre, ce genre de choses..."] = "8493fe09c36205db0684a4321f2d5dcf",
            ["Stormwind est le pilier de la race humaine ; nous la défendrons ainsi que l'ont fait nos ancêtres : de notre volonté et avec des lames affûtées."] = "0a37426688f72de523d491b07d11f473",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
        },
        [915] = {
            ["Ce que j'enseigne ne risque pas de vous intéresser. Cherchez plutôt quelqu'un qui forme des gens de votre classe, $c."] = "0fac9f50e1fb5c48f7301ce81e131b5f",
            ["Je ne pense pas que vous souhaitiez apprendre rien de ce que j'enseigne. Cherchez un maître de votre classe pour vous aider, $c."] = "0fac9f50e1fb5c48f7301ce81e131b5f",
            ["Vous avez l'air de quelqu'un qui aime jouer avec les pièces d'or des autres. Je peux vous aider de quelque manière ?"] = "8ad40600a7b98e4dedc4ac4c244156c2",
            ["Vous êtes le genre de personne près de laquelle il faut surveiller sa bourse. Puis-je faire quelque chose pour vous aider ?"] = "8ad40600a7b98e4dedc4ac4c244156c2",
        },
        [916] = {
            ["Je ne puis vous aider, $n. Je n'entraîne que les voleurs."] = "fa078d44ecb0731e4c2a45f949ae67b1",
            ["Qu'est-ce que je peux faire pour vous, $n ?"] = "22dba637f525eff7a4f6ca7d8c7294cb",
        },
        [917] = {
            ["Mille pardons, mais je ne m'occupe que des voleurs."] = "f4e4bf672f4eaefc2912be4ff2222cd5",
            ["Voyons, voyons... Quelle surprise ! En quoi puis-je vous aider, $c?"] = "a837986a7fc00b64608c3a2074986bbf",
        },
        [918] = {
            ["Ce que j'enseigne ne risque pas de vous intéresser. Cherchez plutôt quelqu'un qui forme des gens de votre classe, $c."] = "0fac9f50e1fb5c48f7301ce81e131b5f",
            ["J'ai quelque chose pour vous, $n. Ça a l'air important."] = "6306d9157dde71c4fa6c0cefe5c64195",
            ["Je ne pense pas que vous souhaitiez apprendre rien de ce que j'enseigne. Cherchez un maître de votre classe pour vous aider, $c."] = "0fac9f50e1fb5c48f7301ce81e131b5f",
            ["Vous avez l'air de quelqu'un qui aime jouer avec les pièces d'or des autres. Je peux vous aider de quelque manière ?"] = "8ad40600a7b98e4dedc4ac4c244156c2",
            ["Vous êtes le genre de personne près de laquelle il faut surveiller sa bourse. Puis-je faire quelque chose pour vous aider ?"] = "8ad40600a7b98e4dedc4ac4c244156c2",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
        },
        [925] = {
            ["Que la Lumière vous protège aujourd'hui."] = "0635f703e43c62457aadee823a30493b",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
        },
        [926] = {
            ["Même si vous ne suivez pas les voies de la Lumière en tant que chevalier de la Main d'argent, n'hésitez pas à nous demander de l'aide !"] = "6d05441079c12f5737a4ae0732070946",
            ["Que la Lumière soit avec vous, $c. En quoi puis-je vous aider ?"] = "0c2e5af8c299738c3e541d7e001d442e",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "31ab172e1a375db1c9157d594eb608d9",
        },
        [927] = {
            ["Que la Lumière vous protège aujourd'hui."] = "0635f703e43c62457aadee823a30493b",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
        },
        [928] = {
            ["Que la Lumière vous protège aujourd'hui."] = "0635f703e43c62457aadee823a30493b",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
        },
        [931] = {
            ["Où voulez-vous aller ?"] = "f6ea55ad6f6344693225294350de4559",
        },
        [944] = {
            ["Salutations, $c. Voulez-vous un conseil ? Devenez l'$gami:amie; d'un mage ! Nous avons plus d'un tour dans notre sac..."] = "a3abb68c7dc7f0e59d1317d10b3a97cd",
            ["Salutations. Je suis un gnome maître des mages et vous êtes un mage."] = "89ebbfb158e8bcf8fa80f49f22684c37",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "a9083a5c3e3237e00bd856dcc0fd400d",
        },
        [957] = {
            ["J'ai l'air d'avoir le temps de me rouler les pouces ?"] = "a14f5faf742204672310f8f5b8263cb5",
            ["Pas mal, mais laissez-moi vous montrer quelques tours que vous trouverez sans doute utiles."] = "bfdb790af74bc4bc8fd2975752784485",
            ["Vous êtes bien meilleur forgeron que moi. Mais je ne l'avouerai jamais publiquement, croyez-moi. Allez parler avec Therum Deepforge. Si quelqu'un peut vous en apprendre plus, c'est bien lui."] = "09a9c4ad934397dc02876bda84bad0ff",
        },
        [963] = {
            ["Je ne comprends pas les officiels de Stormwind, envoyer comme ça notre armée à l'autre bout du monde... Alors que l'ennemi est à nos portes !$B$BAvec les voleurs qui viennent de la marche de l'Ouest et les gnolls qui dévalent de l'est et de l'ouest, c'est un miracle que Stormwind ne soit pas encore assiégé."] = "e03d3aaa8df7e98fcb210403aad69ebd",
        },
        [985] = {
            ["Je n'entraîne pas les gens de votre classe, $c. Trouvez-vous un maître avant que je ne m'énerve."] = "5c32ac92759b0e79eade7dc21f7e569f",
            ["Vous êtes là pour vous entraîner ? Ou votre seul but est-il de faire perdre du temps à un guerrier ?"] = "141f23d07f540e8c7b0ef9335bda601e",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "3a364a4573d4825a6795e3bb454069d4",
        },
        [986] = {
            ["Les Esprits ont guidé votre être jusqu'à moi. En quoi puis-je vous être utile ?"] = "7857c55cf19a633dd72142ae5b1f6578",
            ["Que les Esprits soient avec vous !"] = "e7a2c0dc7f07afebb450c37adc691ede",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "3a364a4573d4825a6795e3bb454069d4",
        },
        [987] = {
            ["Ne me faites pas perdre mon temps."] = "77d31ff418c404f97bed5fd865e38ebe",
            ["Quoi ?"] = "473178aa39ca6564bcadca7c21bbfead",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "3a364a4573d4825a6795e3bb454069d4",
        },
        [988] = {
            ["Votre volonté n'est pas assez puissante pour manipuler les forces que nous contrôlons, $c."] = "5a92f47cf481eb3def2615b8693c94fc",
            ["Vous en savez assez pour représenter un danger, mais je crois que vous avez encore besoin de vous perfectionner, $n."] = "f097ab331f582c2d79e805e164a7c169",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "3a364a4573d4825a6795e3bb454069d4",
        },
        [1071] = {
            ["S'il y a une chose que le temps m'a apprise, c'est qu'aucune mission n'est ennuyeuse.  Protéger la Travée de Thandol aurait dû être une tâche facile.  Mais le gros de l'armée s'étant battu aux côtés de l'alliance, nous avons été submergés ici et Dun Modr est tombé."] = "f1d14ab32292c3872c0b525fe554f79d",
        },
        [1103] = {
            ["Alors, vous voulez parfaire vos connaissances ? Je ne demande pas mieux que de vous aider."] = "c9603b8eec1e5738749f40b5e7e89a19",
            ["Je peux vous assurer que votre garde-robe a vraiment besoin de soins."] = "b34aad75e8e14753d5e47ece1a2eba61",
            ["Je suis un homme simple qui connaît deux ou trois choses sur la coupe des vêtements, mais vous avez besoin de plus de conseils que je ne peux en fournir. J'ai entendu parler d'un elfe de la nuit susceptible de vous aider. Il se trouve à Stormwind, dans le Quartier des mages."] = "c20cda58878fc7ac4e481f3bc65a3f73",
        },
        [1105] = {
            ["Vous savez, j'ai toujours voulu être prospecteur, mais je suis né avec une tête pour les chiffres et la Guilde a décidé que je serais plus apte à tenir les livres ! J'ai étudié, étudié, chaque jour de ma jeunesse..."] = "2224ccf915581b20ff86f4df54a1c6e3",
        },
        [1139] = {
            ["Bonjour, citoyen. Je m'appelle Bluntnose, le magistrat Bluntnose, pour être précis. Je suis chargé de veiller au bien-être du Thelsamar, et croyez-moi, nous avons toujours besoin d'une autre paire de bras solides par ici !"] = "1603eccbffa38c44d4f3bf8a2cfcd29e",
        },
        [1141] = {
            ["Si vous êtes ici pour la nourriture, alors bienvenue !  Vous ne trouverez pas de meilleur repas dans tout Stormwind... ou Azeroth !$B$BSi vous êtes ici pour autre chose, soyez bref.  J'ai une douzaine de plats en préparation, et je dois m'occuper de chacun d'entre eux."] = "1a2aa346a91caa0210698f8d84a7023f",
        },
        [1154] = {
            ["Ici, au pavillon des Pérégrins, nous apprécions surtout les compétences de chasseur. Vous voulez ma protection ? Il faut la mériter !$B$BVous avez l'air à la hauteur de la tâche, $g mon gars:ma petite;."] = "b9a009c23ae18be4d2beb4d5b487dd08",
            ["Vous êtes un chasseur de quelque talent, $N ! Vous avez prouvé vos mérites, vous avez également battu Daryl, ce qui n'est pas rien selon moi !$B$BRevenez quand vous voulez !"] = "f5c3b81ff7aa2cea4c40a37dadb0f053",
        },
        [1156] = {
            ["Bienvenue au pavillon des Pérégrins, $N !"] = "acbe16ea3d149deb13ccd9048db985c9",
            ["Prenez cette tête, vous ne manquerez pas de flanquer une bonne trouille à Daryl. Ce n'est pas qu'il ne le mérite pas, ce bâtard arrogant. Mais ah, j'ai hâte de voir sa tête quand vous lui montrerez !"] = "675474e0619645670f8ac5fe9a9fadbf",
        },
        [1215] = {
            ["Bonjour, $gmonseigneur:madame;. Je vous serrerais volontiers la main, mais je suis en plein travail. Je peux vous aider ?"] = "fc05789524675185326e36bb917847b7",
            ["C'est un bon début, mais vous avez encore beaucoup à apprendre, $n."] = "8d1a9653ec0ac81cbb827f31a1138bda",
            ["Vous savez déjà tout ce que je suis susceptible de vous apprendre, $N. Parlez à Lilyssia Nightbreeze, l'elfe de la nuit, dans le quartier des mages de Stormwind, si vous voulez continuer vos études. Il paraît que c'est un bon professeur."] = "00ac4b235ec0f2725dd99c50a0ed9648",
        },
        [1226] = {
            ["J'espère que la Lumière est avec vous, $N. En quoi puis-je vous aider ?"] = "238a7cdf16a7d258e1b3789d98c5e7fb",
            ["Que la Lumière vous protège, $c."] = "852369f0d2fbc11e555e75fe5a433853",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "31ab172e1a375db1c9157d594eb608d9",
        },
        [1228] = {
            ["Salutations, $c. Permettez-moi de vous donner un conseil. Lors de vos voyages, prenez garde à la magie, car elle brûle les non-initiés."] = "8fd77c576e61a6ac69420c6902a2153b",
            ["Salutations. Je suis un Maître des mages et vous êtes un mage."] = "ba87bd521b00c273a44207b174b44c7a",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "a9083a5c3e3237e00bd856dcc0fd400d",
        },
        [1229] = {
            ["Les grandes guerres ont beau être finies, il nous faut poursuivre notre entraînement !"] = "ce85977b0f1b155023ca49641a927acd",
            ["Vous n'êtes pas un guerrier... Le dernier $c que j'ai entraîné n'a même pas tenu une journée.$B$BRegardez-moi ça, encore $gun gros malin:une petite futée; qui se prend pour un guerrier... Ah !"] = "64a04066374cb355ff1adeae11f4ae82",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "31ab172e1a375db1c9157d594eb608d9",
        },
        [1231] = {
            ["J'peux pas vous aider. Trouvez-vous un maître de vot'classe, $c."] = "65ffa984c80ec793cab656acd848ac8c",
            ["Qu'est-ce que j'peux faire pour vous ?"] = "ff4c1db50d39977890db3fe889ea21ae",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "31ab172e1a375db1c9157d594eb608d9",
        },
        [1232] = {
            ["Même si vous ne suivez pas les voies de la Lumière en tant que chevalier de la Main d'argent, n'hésitez pas à nous demander de l'aide !"] = "6d05441079c12f5737a4ae0732070946",
            ["Que la Lumière soit avec vous, $c. En quoi puis-je vous aider ?"] = "0c2e5af8c299738c3e541d7e001d442e",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "31ab172e1a375db1c9157d594eb608d9",
        },
        [1234] = {
            ["Je ne puis vous aider, $n. Je n'entraîne que les voleurs."] = "fa078d44ecb0731e4c2a45f949ae67b1",
            ["Qu'est-ce qui vous amène ici, $n ?"] = "cdcf0443cbf0e6c89324a0d43261fbd6",
        },
        [1239] = {
            ["Si vous êtes prêt à endurer des histoires qui vous feront frissonner et vous dégoûteront, prenez un verre et asseyez-vous un moment..."] = "b22ef4b159c4d30560b2e0b7fa1b6fea",
        },
        [1241] = {
            ["Bien le bonjour jeune $g homme:fille;. En quoi puis-je vous être utile ?"] = "9e8b94c1be7b802ff587b91f7fd1bd92",
            ["Vous apprenez vite, jeune $g homme:fille;, trop vite pour moi. Si vous voulez poursuivre votre formation, je vous suggère de rencontrer mon maître. Son nom est Rotgath, Rotgath Stonebeard, et vous le trouverez dans Ironforge, à la Grande Forge."] = "b87832ee885e2c2b541409175c3036f5",
            ["Vous êtes là pour l'entraînement, hein ? Je commence ma formation moi-même, mais je veux bien vous enseigner ce que je sais."] = "5fcded33d34a5f55fd70058a5461f5ed",
        },
        [1243] = {
            ["Hegnar Rumbleshot, à votre service !"] = "021dde6de017478913faed817d53af98",
        },
        [1246] = {
            ["Je ne peux rien vous enseigner, $N. Parlez à Tally Berryfizz, par là. Elle peine à atteindre les tables, mais quand elle commence à préparer une potion, faites attention !"] = "39ebd1b988bad54e8ab04456d49fb6c9",
            ["Ne laissez pas ces grands yeux innocents vous tromper. Tally s'y connaît parfaitement. J'apprends chaque jour quelque chose de nouveau. Pourquoi croyez-vous que je suis ici à Brikabrok ? Est-ce que j'ai l'air d'un ingénieur ? Je ne crois pas."] = "32a5626d8140ad954652c141442fc86c",
            ["Remettez sans cesse votre ouvrage sur le métier, $gmon garçon:jeune fille;. Le travail et la détermination, c'est la seule méthode ! Ne laissez personne vous dire que les livres sont une instruction suffisante !"] = "94877755c9cc3beb33d35c6e3279a7f0",
        },
        [1247] = {
            ["Les gages d’amour sont de petits messages d’affection que vous pouvez donner aux habitants des villes et des capitales qui ont le cœur à l’amour. En échange, elles vous offriront un cadeau d’adoration.$B$BSi vous êtes déjà $gadoré:adorée; par quelqu’un d’autre, elles vous remettront au moins un cadeau d’amitié."] = "64973aa51308c04b55be79da97ac51f1",
            ["Moi non, mais beaucoup de gens cherchent l’amour. Vous devriez mettre un peu de parfum ou d’eau de Cologne, acheter mes gages d’amour, et les faire circuler !"] = "e76319f8e0a3393f78b709a653ebd046",
            ["Qu'est-ce que vous pouvez faire dans une auberge ?$B$BEh bien, vous pouvez vous reposer confortablement. Et à grâce à cela, vous serez 'bien $greposé:reposée ;', plus rapidement que si vous étiez dehors. Et quand vous êtes bien $greposé:reposée;, vous profitez plus de votre expérience.$B$BVous pouvez aussi parler avec l'aubergiste pour obtenir une Pierre de foyer, afin de pouvoir revenir plus rapidement dans cette auberge."] = "7559d6906f8128171c86805ac0f7eaac",
            ["Quand vous donnez des gages d'amour aux habitants des villes, vous recevez différents cadeaux en retour. Vous pouvez en garder ou en utiliser certains, mais vous pouvez aussi en faire des assortiments que vous donnerez à votre héros préféré !$B$BAllez voir Kalin Colportecoeur pour donner vos cadeaux.$B$BVous pourrez trouver Kalin près de Bolvar, Magni et Tyrande."] = "490f61093d0ec9e8887f5611d0dde3c6",
            ["Quand vous donnez des gages d'amour aux habitants des villes, vous recevez différents cadeaux en retour. Vous pouvez en garder ou en utiliser certains, mais vous pouvez aussi en faire des assortiments que vous donnerez à votre héros préféré !$B$BAllez voir Kalin Colportecoeur pour donner vos cadeaux.$B$BVous pourrez trouver Kalin près de Cairne, Sylvanas et Thrall."] = "a6db9e7560aabbf0956453b311a6e920",
            ["Remplissez votre chope et prenez une chaise. Nous avons des histoires à raconter et des tonnelets à vider."] = "c3684d8296958c5935a2740fa7611b74",
            ["Si vous mettez de l’eau de Cologne ou du parfum, vous verrez qui a le cœur à l’amour. Tous acceptent les gages d’amour… et vous offrent un don en échange.$B$BAttention, pour donner un gage d’amour à quelqu’un, vous devez avoir la bonne odeur. Les hommes aiment l’odeur du parfum, et les femmes celles de l’eau de Cologne."] = "e74b227d686c3a09c784a937420b00fc",
        },
        [1254] = {
            ["Les trognes ! Je jure que les dieux les ont mis sur cette terre uniquement pour me tourmenter ! Quatre pouces de plus dans les mines, puis deux pieds de recul par rapport aux trognes !"] = "028e5bed04e8188efd6d0cab5fc56e8f",
        },
        [1257] = {
            ["La meilleure affaire de Stormwind, mon $g ami:amie;, je vous le dis. Vous ne trouverez rien de meilleur. En quoi puis-je vous être utile ?"] = "0a50227fd4a79a221c5e74147031f06e",
            ["La meilleure affaire de Stormwind, mon $gami:amie;, je vous le dis. Vous ne trouverez rien de meilleur. En quoi puis-je vous être utile ?"] = "0a50227fd4a79a221c5e74147031f06e",
            ["Vous vouliez juste regarder ou y a-t-il quelque chose de précis que vous cherchez ?"] = "a86de99ac7614f683ab7eab24b0a0b93",
        },
        [1261] = {
            ["On ne sait pas ce qu'est une monture tant qu'on n'a pas fendu le vent sur un bélier des montagnes de Barak Tor'ol ! N'hésitez pas à inspecter ces fiers compagnons d'aventure. Ils vous serviront bien, vous verrez."] = "3caea1966e7ba5ccaa3d5ba89520c93f",
            ["Pas si vite, $gmon gars:mademoiselle;. Je ne vous donnerai pas les rênes d'un de nos béliers de course si vous n'êtes pas $gun allié affirmé:une alliée affirmée; des nains d'Ironforge. Lorsque vous serez $greconnu:reconnue; comme $gexalté:exaltée; à Ironforge, j'aurai plaisir à vous montrer notre sélection de montures."] = "5953f84af6e63c466e0a1f64d4a3f981",
        },
        [1267] = {
            ["Bienvenue à la distillerie Thunderbrew, fondée par notre cher vieux papa, Arkilus Thunderbrew.  J'assure le fonctionnement de l'établissement depuis que mon frère aîné, Grimbooze, a disparu dans un état d'ébriété il y a quelques récoltes."] = "16210fbff7e9a04c6c9ea97276069126",
        },
