        },
        [1300] = {
            ["Hmm... Les choses que vous avez besoin d'apprendre me dépassent quelque peu. Parlez à Sellandus, des Drapiers Larson, un peu plus loin sur la droite. Il m'a enseigné tout ce que je sais !"] = "35b7486429188df700dbf11b3bbcbd82",
            ["La vie ressemble à une tapisserie finement brodée."] = "e70d13a96c407b1d174c59f1f077a835",
            ["Très bien ! Que commence votre voyage dans l'art du Tailleur !"] = "c5f30755100cfd7f05cda25a366d0602",
        },
        [1301] = {
            ["La meilleure affaire de Stormwind, mon $g ami:amie;, je vous le dis. Vous ne trouverez rien de meilleur. En quoi puis-je vous être utile ?"] = "930e45368ed7dcac8e799df8fa5bc730",
