        },
        [1311] = {
            ["Bienvenue au Solitaire bleu, où les pratiquants de magie viennent se rassembler et se défouler. Que puis-je faire pour vous, $gmonsieur:madame; ?"] = "386f37176e6f7b06d34487928a573d23",
        },
        [1312] = {
