        [3043] = {
            ["Je ne peux pas vous former, $c."] = "9404079002e176274c2ff652c8208428",
            ["Peu importe combien on apprend, il y a toujours plus à savoir."] = "4a6a6065163c56f554d467ae1dc50637",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "0ad2a902852beef6cfe7ead6b6979fff",
        },
        [3044] = {
            ["Ah, vous êtes $gcelui:celle; qui a trouvé la lettre. Merci pour ces... nouvelles, en quelque sorte, de ma famille. Prenez donc à manger et à boire."] = "c5b7759f0cefd29b1a309325dd586e97",
            ["Oui, $c ?"] = "901d3b1160b38eacb61be277a1eab438",
            ["Que peut pour vous cet insignifiant serviteur, $N ? Vous entraîner peut-être ?"] = "ca5ae8d63433bb1a991ae3a7d4a633fc",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "a54fabb9fc0936c92134f8611f4e5e8b",
        },
        [3045] = {
            ["Oui, $c ?"] = "901d3b1160b38eacb61be277a1eab438",
            ["Que peut pour vous cet insignifiant serviteur, $N ? Vous entraîner peut-être ?"] = "650cd75a030b0fef3f59f216d895e8d1",
