        },
        [5491] = {
            ["Que la Lumière vous protège aujourd'hui."] = "0635f703e43c62457aadee823a30493b",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
        },
        [5492] = {
            ["Que la Lumière vous protège aujourd'hui."] = "dc28bc0a4d37e6ffcda4039181cfd698",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "768f0928588ebe52253715a9f6b21ad7",
        },
        [5493] = {
            ["Bienvenue à Stormwind. La reconstruction fut longue, mais nécessaire. Vous venez pour visiter ou pour affaires ?"] = "e980a3fd7dce3ba0d906cea472aaa320",
        },
        [5494] = {
            ["La meilleure affaire de Stormwind, mon $g ami:amie;, je vous le dis. Vous ne trouverez rien de meilleur. En quoi puis-je vous être utile ?"] = "930e45368ed7dcac8e799df8fa5bc730",
            ["La meilleure affaire de Stormwind, mon $gami:amie;, je vous le dis. Vous ne trouverez rien de meilleur. En quoi puis-je vous être utile ?"] = "930e45368ed7dcac8e799df8fa5bc730",
            ["Vous vouliez juste regarder ou y a-t-il quelque chose de précis que vous cherchez ?"] = "b27e9e38daaae8b0ac9e5d7775fe5a70",
        },
        [5495] = {
            ["Les arcanes ne corrompent que les faibles. Continuez votre formation ou vous connaîtrez un sort similaire."] = "c381816693d5bcf8cf6644c3ad7a0dea",
            ["Les ténèbres vous rejettent, $c. Cessez de me casser les oreilles et sortez de ma vue. Disparaissez !"] = "2aabd37566ced1f9550e86910bb3baf8",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "768f0928588ebe52253715a9f6b21ad7",
        },
        [5496] = {
            ["Les arcanes ne corrompent que les faibles. Continuez de vous entraîner, ou vous subirez le même sort."] = "7533bf57cdb44c24f4dde1a0d3b1909a",
            ["Les arcanes ne corrompent que les faibles. Continuez votre formation ou vous connaîtrez un sort similaire."] = "7533bf57cdb44c24f4dde1a0d3b1909a",
            ["Les ténèbres vous rejettent, $c. Cessez de me casser les oreilles et sortez de ma vue. Disparaissez !"] = "c4bef13520e7f7e2f4078fbe96c02345",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
        },
        [5497] = {
            ["Salutation, mage. Puis-je vous offrir une nouvelle vision du monde de la magie ?"] = "385f571d2bb437e712de5a8637774ac6",
            ["Salutations, $c. Permettez-moi de vous donner un conseil. Lors de vos voyages, prenez garde à la magie, car elle brûle les non-initiés."] = "99ae39f09db2040d0e2e3bcddb52b4b7",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "768f0928588ebe52253715a9f6b21ad7",
        },
        [5499] = {
            ["Coincée dans cette petite maison, je rêve de participer aux combats qui font rage à l'extérieur de la ville. Mais j'ai pour devoir de partager mes connaissances avec ceux qui combattent pour notre camp. Du moins, pour l'instant."] = "ed08741e0fa329d057d7599e24228bde",
            ["Mon enseignement est trop pointu pour vous pour l'instant. Si vous voulez apprendre à faire davantage de potions, rendez visite à Tel'Athir, qui se trouve juste là."] = "5267bc8c8e1e686d26269a5f3ff09120",
            ["Vous avez dépassé mes maigres compétences. Cherchez l'elfe de la nuit Ainethil à la terrasse des Artisans de Darnassus. Elle saura vous faire aller plus loin. Je voudrais pouvoir aller avec vous."] = "74a70a5ebb282b79045b51aecca1ec33",
            ["Écoutez attentivement, $n, car j'ai beaucoup de connaissances à partager."] = "0ead8c4b512091b1c2251831fa68e99b",
        },
        [5500] = {
            ["C'est un honneur pour moi de partager mes connaissances avec vous, $n. Faites en sorte de les utiliser à bon escient."] = "cfb248e2ebbfc3cd75c431e2ae22550c",
            ["Ishnu-alah ! Avez-vous des nouvelles de l'étranger ? Mon cœur languit de Teldrassil."] = "aff74adc7cfe1e9be08e74e833079838",
            ["Vous devez choisir un Maître plus expérimenté, car vous avez surpassé mes aptitudes. Je vous conseille de parler à Lilyssia Nightbreeze, elle a beaucoup à offrir."] = "e81f895ec54ec796b942787aa21a7e8d",
        },
        [5501] = {
            ["Bienvenue au Cercle cénarien, $c. En quoi puis-je vous aider ?"] = "7dd7ee318342731a34bf5316088d4c74",
            ["Je ne peux pas entraîner les membres de votre classe, $c."] = "f2c2c7d6984ce15c597fe07b1c728e29",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "30ee103c545f987ab518c70f6d3e640e",
        },
        [5502] = {
            ["J'espère que vous ne m'interrompez pas pour rien ; j'étais sur un travail de grande importance."] = "1350458c0cd4617f19601567a9a4d9f2",
            ["Un autre herboriste, hum. Je doute que vos compétences égalent les miennes ; je peux par conséquent vous apprendre quelques techniques utiles."] = "e5d7ea0ee1b3b55a8e19cbb4d7d4bf32",
        },
        [5503] = {
            ["Fait par les meilleurs artisans de Teldrassil, convoyé de Kalimdor à Azeroth, en honneur de l'alliance entre ceux du Grand Arbre et les humains de ce pays. Vous voulez quelque chose ? Demandez !"] = "f819d1b4e7f5fee1a4f4efd60581493e",
        },
        [5504] = {
            ["Bienvenue, $gmon frère:ma sœur;. Si vous êtes ici pour apprendre, j'aurai grand plaisir à vous enseigner.$B$BBientôt, vous entendrez l'appel du Rêve d'émeraude. Vous hibernerez pendant des années et marcherez parmi les formes les plus pures. C'est là que votre ultime formation aura lieu."] = "1d12fd8e421d229eea70c7677a2daeca",
            ["Même entre de froids murs de pierre comme ceux qui entourent cette ville, on peut trouver la tranquillité et la paix. En fait, on peut les trouver où qu'on soit... Il faut chercher en soi cet équilibre..."] = "922a94a8f826437fe0370bdcd6a587ac",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "30ee103c545f987ab518c70f6d3e640e",
        },
        [5505] = {
            ["Bienvenue, $gmon frère:ma sœur;. Si vous êtes ici pour apprendre, j'aurai grand plaisir à vous enseigner.$B$BBientôt, vous entendrez l'appel du Rêve d'émeraude. Vous hibernerez pendant des années et marcherez parmi les formes les plus pures. C'est là que votre ultime formation aura lieu."] = "1d12fd8e421d229eea70c7677a2daeca",
