        [11139] = {
            ["Où voulez-vous aller ?"] = "f686b3319d4af5004c6ee3403aea3f5e",
        },
        [11145] = {
            ["Salutations, $N. Je suis Myolor Sunderfury, gardien de la Grande Forge."] = "ea87f9213413c02d4186b43c3b1f15ad",
            ["Vos dons de forgeron sont exceptionnels, $N. Il est temps de prendre une décision. Vous pouvez choisir entre deux voies : Fabricant d'armes ou fabricant d'armures.$B$BFaites attention, une fois que vous aurez choisi une voie, vous ne pourrez plus changer d'avis. La discipline requise par chaque voie ne laisse pas de place aux mélanges."] = "2f8c9ab139c42a81d62532751c158627",
        },
        [11146] = {
            ["Salutations, $r."] = "ff6b7b64cb17b855134fc86b013b44ba",
        },
        [11176] = {
            ["Je suis Krathok. Je supervise ces artisans."] = "7e9d679addb34d3d0807c78bae52c702",
            ["Lorsqu'un forgeron atteint votre niveau de maîtrise, je lui propose un choix.$B$BVous n'avez pas besoin de prendre une décision, mais c'est tout de même recommandé. Vous ne voulez pas rester un débutant jusqu'à la fin des temps, hein ? Ce sont les fabricants d'armes et d'armures qui ravitaillent nos armées, gagnent nos guerres et se font acclamer !$B$BMais attention, $N. Une fois que votre choix est fait et les tâches demandées accomplies, vous ne pourrez plus changer d'avis. On ne peut marcher que sur une seule route."] = "96173540913b1a1b1f52b21095a0971e",
        },
        [11177] = {
            ["Que voulez-vous ?"] = "a9064d83aa3ba7a86a2ff7346ed99f64",
        },
        [11178] = {
            ["Salut, $c !"] = "fd41c7dea4e93768079bd2529e97c608",
        },
        [11191] = {
            ["Je vais vous apprendre à forger des marteaux. Il suffit de demander gentiment."] = "36713901087518deca258af947863cc9",
            ["Ne vous approchez pas trop, $n. Je risque de dévier et de vous défoncer la cervelle avec mon marteau."] = "e2dd7fbda6eda67036e13d4fbe105755",
        },
        [11192] = {
            ["Ah, vous étiez un vétéran expérimenté. Kilram peut vous faire le redevenir. Je sais que vous en êtes capable. Il suffit que vous demandiez et je vous apprendrai à fabriquer des haches."] = "6d7eb7644ad83f313e5d689284fb3b48",
            ["Je suis Kilram, maître de la hache."] = "9bd36faf52beb6ae72539e0731c74b9d",
        },
        [11193] = {
            ["Reculez ou je vous coupe en deux."] = "06af0379d0a4f27cb78f8ccab80db4c6",
            ["Si vous souhaitez devenir fabricant d'épées, il suffit de demander."] = "f6dd091cd31c13e889f5415aa70a5dd6",
        },
        [11216] = {
            ["Bonjour, jeune $ghomme:femme;. Je suis Eva Sarkhoff et voici mon mari, Lucien. C’est un plaisir que de faire votre connaissance."] = "719242cbbf2aa59d701d86713c8c3252",
            ["Certainement. Nous avons autrefois servi dans la maison Barov, qui est maintenant connue sous le nom de Scholomance.$B$BJ’étais servante en chef et Lucien était le majordome de Maître Barov.$B$BNous avons travaillé pour les Barov pendant de longues années, jusqu’à ce que...$B$B<Eva sanglote.>"] = "756458ddc837d604fed920f729482517",
            ["Des liens ? Non… il y a des choses sur cette terre qui sont bien plus puissantes que de simples chaînes ou barreaux pour tenir quelqu’un prisonnier, jeune $ghomme:femme;. Les morts-vivants nous tournaient autour, ne cessant de nous tourmenter par des actes abominables.$B$BFinalement, il vint. Il se présenta sous le nom de docteur Theolen Krastinov, mais nous allions apprendre à le connaître sous son autre nom : 'le Boucher'."] = "69e44cddca5438e4e1af0254c4b88beb",
            ["Le Boucher nous parlait sans arrêt du 'sang des innocents', de son maître, 'Kirtonos', et de l’obligation qu’il avait de le satisfaire.$B$BFinalement, l’infâme en eut fini avec ces expériences. Nous avions été vidés de toute vie ; nos esprits étaient en miettes. Nous n’attendions que le doux baiser de la mort pour nous libérer. Mais dans son infinie cruauté, le Boucher referma devant nous les portes de la mort.$B$BNous étions destinés à rester en vie pour nourrir ses goules voraces. Il riait à gorge déployée en regardant comme ces créatures se repaissaient de notre chair."] = "a7270f1782361fe639b53192b48d3021",
            ["Nous avons finalement compris d’où venaient les cris. Le Boucher nous soumit à des affres dont nous ignorions qu’ils pussent exister. Il pratiqua des expériences hideuses sur nous, essayant de créer une sorte de peste en se servant de nous comme de cobayes.$B$BLes jours devinrent des semaines et nous serions morts dès le premier jour si cet être infâme n’avait utilisé des moyens magiques pour nous conserver en vie."] = "8a7ceb21fd9d2dc97d7ae354831bff4d",
            ["Nous avons vécu ainsi pendant six mois, assistant à la chute de la maison Barov, spectateurs d’évènements toujours plus horribles. Des créatures hideuses rôdaient dans le manoir en toute liberté. Des sectateurs des ténèbres avaient couvert les murs et le sol de divers objets rituels et sacrificiels. Nous savions que nous ne pourrions nous cacher indéfiniment.$B$BComme nous nous y attendions, nous avons fini par être repérés et capturés. Ils nous ont ôté tous nos vêtements et nous ont allongés au centre d’un cercle de sang. Nous sommes demeurés ainsi, nus et tremblants, pendant plusieurs jours."] = "70ebec19d6bac1a72ab166bf72b88a89",
            ["Nous ne ressentons rien. Nos âmes restent ici, dans les limbes. Nous ne pourrons pas partir tant que nos dépouilles n'auront pas été retrouvées pour donner la paix à nos esprits."] = "edc58a5c1c56476d66c018d555211d77",
            ["Nous pensons que pour préserver leur fortune et leur pouvoir au-delà de la mort, les Barov ont conclu un marché avec un puissant mage humain, un certain Kel'Thuzad.$B$B<Eva frissonne.>$B$BC’est à cette occasion qu’est apparue l’école de nécromancie, un lieu voué au Culte des damnés, qui devint leur capitale.$B$BLes semaines passant, la maison Barov fut de plus en plus corrompue.$B$BDes créatures des ténèbres s'installèrent dans les différentes ailes de la maison, rendant l’entretien et le nettoyage aussi irréalisables qu'écœurants."] = "c5cf5c7edf079b63f339d577611fcc5e",
            ["Oh, c’est affreux, $gmonsieur:madame;, la maison Barov était jadis pleine de vie et de splendeur. Le manoir était la résidence principale des Barov, mais leurs possessions s'étendaient au loin.$B$BLucien et moi avons remarqué que, le temps passant, les Barov sont devenus dépressifs. Les crises de paranoïa et de fureur devenaient de plus en plus fréquentes chez nos maîtres. La nuit, nous pouvions les entendre se disputer dans leurs appartements. D’après ce que nous avons pu comprendre, leur avidité avait gagné sur leur raison et l’avait dévorée."] = "af8171848b9bed576fbbef9cbc14cfea",
            ["Pour aller où ? Nous ne connaissons pas d’autre travail et ne pouvons vivre autrement.$B$BÀ la fin, nous avons complètement perdu contact avec les Barov et avons été mis à l’écart du ménage. Nous ne savions pas ce qui arrivait aux autres domestiques, mais nous entendions souvent des cris de détresse, des cris terribles déchirer le silence.$B$BSachant que nous n’avions nulle part où aller, Lucien et moi avons été forcés de nous cacher dans nos anciens quartiers. Pendant la journée, mon mari se glissait à l’extérieur et allait glaner un peu de nourriture."] = "b065b568de2e8281a8a07ba46fb7e67a",
        },
        [11259] = {
            ["Desolace n'est pas un si mauvais endroit, si vous n'êtes pas gêné par les harcèlements constants des centaures."] = "f665bec7d52af8ff76a10cb1e23a6f8c",
        },
        [11277] = {
            ["Bienvenue à Caer Darrow, $gétranger:étrangère;."] = "7865da4630a47f9938f5a4dfce34dadf",
            ["Encore une belle journée dans notre île magnifique."] = "6ee2df979a0ec4486607c25f530d005f",
            ["Nous ne sommes pas vraiment discourtois, mais tout le monde est pressé, tout doit être parfait pour l'arrivée d'Uther. Ce n'est pas tous les jours que le Porteur de Lumière vient en ville."] = "3fd0ad73fe861332551fc4d9af524377",
            ["Vous avez essayé notre pain ? Le boulanger Masterson est à coup sûr le meilleur cuisinier de l'histoire."] = "f46f6654ac94eac82e2b0c3924d865e1",
            ["Vous ne voyez pas que nous nous préparons pour la visite d'Uther ? Hors de ma vue, maintenant ! J'ai du travail !"] = "4e2408ee8c09379d77525ec8b38e694d",
        },
        [11279] = {
            ["Attention où vous mettez les pieds. Nous ne voulons pas de bandits dans notre ville."] = "a97a57480f28e32779349ee115d11474",
            ["Bah, vous avez l'air $gdu dernier des mendiants:de la dernière des mendiantes;..."] = "f4a68005ee615866bd6901fa901730b9",
            ["Ici, on ne jure pas, on ne se bat pas, on ne vagabonde pas... Vous êtes à Caer Darrow."] = "4c4f28300ec91dd44dcc6b9766779e5d",
            ["Je ne suis que rage et hostilité. Donnez-moi seulement un prétexte, et..."] = "8aefd7ed4734fdad575f3aa8cabd868b",
            ["Je vous ai à l'oeil, $r."] = "98696987285136bfb07bf8b6b4ca71f2",
        },
        [11281] = {
            ["Attention où vous mettez les pieds. Nous ne voulons pas de bandits dans notre ville."] = "a97a57480f28e32779349ee115d11474",
            ["Bah, vous avez l'air $gdu dernier des mendiants:de la dernière des mendiantes;..."] = "f4a68005ee615866bd6901fa901730b9",
            ["Ici, on ne jure pas, on ne se bat pas, on ne vagabonde pas... Vous êtes à Caer Darrow."] = "4c4f28300ec91dd44dcc6b9766779e5d",
            ["Je ne suis que rage et hostilité. Donnez-moi seulement un prétexte, et..."] = "8aefd7ed4734fdad575f3aa8cabd868b",
            ["Je vous ai à l'oeil, $r."] = "98696987285136bfb07bf8b6b4ca71f2",
        },
        [11285] = {
            ["Ils ne réalisent pas qu'ils sont morts, $r. Ils sont condamnés à revivre leur dernier souvenir d'avant que leur ville ne soit dévorée de l'intérieur. La plupart d'entre eux, en tout cas. Certains ont eu moins de chance.$B$BVous pensiez que c'était la faute du Fléau ? Le Fléau n'existait même pas et s'il s'était agi d'eux, au moins nous aurions pu nous battre.$B$BNon, c'est le résultat d'une peste venue de Scholomance et qui a ravagé la ville. C'était horrible, un cauchemar. Nul n'a survécu.$B$BLaissez-moi, maintenant. Je n'ai pas encore assez pleuré."] = "313febb63dee5a7c62e6bd14ad042eb5",
        },
        [11286] = {
            ["Ah, je suppose que je me laisse emporter. Ras Murmegivre est le maître de cette école. L'être qui forme toutes ces créatures des ténèbres. Un lieutenant et un favori de Kel'Thuzad. Il fut naguère un mage ambigu de Stromgarde : un magicien indépendant qui ne fut pas instruit à Dalaran.$B$BLorsque Kel'Thuzad fonda le culte, Ras fut l'un des premiers à rejoindre ses rangs. Ras savait que par la magie noire, il atteindrait l'immortalité."] = "51cb986edcfa270e6cc5822e28aea6d5",
            ["Bien. Pour que mon plan fonctionne, nous devons d'abord créer une pierre de vie. Vous pensez pouvoir agir ?"] = "860337aafa61acb9bf89d39d7d7e5df9",
            ["C'est très simple, en fait. Volez ses pouvoirs à la liche Ras Murmegivre. Renvoyez-le à sa forme mortelle et là, vous pourrez le tuer une fois pour toutes."] = "5ccab19ac455820f916fd02a08fcb67c",
            ["Certains se sont vus épargner l'angoisse des souvenirs."] = "617c23db3203cf0d7bf17c56cc4f725a",
            ["Doucement, $r. Celui que vous devez tuer est déjà mort. Le tuer de nouveau ne servira à rien. Il n'y a guère de moyens de détruire une liche, et nous ne pouvons rien faire pour l'heure. Mais j'ai un plan. Un plan qui aura un véritable impact sur le Culte."] = "3654a5858970316abe17dd3eeaa6ad6f",
            ["Il y est parvenu. Il a rapidement gravi la hiérarchie du culte, et le roi-liche lui a donné l'immortalité. C'est ainsi qu'est né Ras Murmegivre, la liche.$B$BVous comprenez, à présent ?"] = "3f405996544104f75a50b759d3498828",
            ["Le Culte des damnés a encore progressé. Presque chaque ville, des capitales aux petits hameaux, dans la Horde comme dans l'Alliance, abrite des membres du culte.$B$BNe prenez pas cet air surpris. Ils ne portent d'uniformes que pour les rituels et les cérémonies. Il est possible que vous ayez tissé des liens avec l'un d'eux sans même le savoir."] = "5531b0711b11aa45460840d0d2c1ab10",
            ["Rien. Vous pouvez les ralentir, peut-être.$B$BLa Scholomance est leur principale source d'entraînement et d'éducation. C'est là que les membres du culte se forment avant de se répandre dans nos sociétés.$B$BIl faut frapper à la source. Au coeur du Culte des damnés !"] = "7bea42e5121470dc3f74c222342d2d9d",
            ["Vous croyez ? Ils ont toujours opéré de cette manière. Qu'est-ce qui fait la force de Kel'Thuzad et de l'armée sans cesse plus nombreuse du Fléau ? Un disciple fanatique et bien vivant qui prépare leur chemin dans la cité et déchaîne soudain une peste qui détruit les gens par milliers ou un simple soldat mort-vivant ? Vous n'êtes pas assez stupide pour vous laisser avoir.$B$BCroyez-moi, $r, ils vivent, travaillent et complotent parmi nous."] = "6ac3dfebce6f1d216515255cab46fcf0",
        },
        [11316] = {
            ["Ah, ma douce Brandy, elle me manque tellement !"] = "d0de32a7070d9141f53ed58970f3f5f2",
            ["En fait, je suis officiellement Spécialiste de la Gestion des Déchets."] = "a7ed0b69c3f96a8b2db61ded1d58a42b",
            ["La maison Barov me donne beaucoup de travail. Il en sort toujours des détritus quelconques."] = "03a7c357a0ab51cdaf720c6be5d6d491",
            ["Vous devriez peut-être parler à ces outils de propagation du son attachés à mes POINGS DE FURIE."] = "cbac7251f7cadd2e49d055da41a352e5",
        },
        [11317] = {
            ["Salut ! Vous avez déjà plongé profondément sous l'eau ? Je vais vous confier un petit secret. Au plus profond des océans, il y a des fissures bouillonnantes qui libèrent des bulles d’air : elles permettent de respirer sous l'eau. Que ce secret reste entre vous et moi, hein ? Je ne veux pas de concurrents qui viendraient piller mes casiers à crustacés... Si vous voyez ce que je veux dire !"] = "4e6ffc14d0d8a4483a2dcdfc8694ccbf",
        },
        [11397] = {
            ["Ma sagesse est à vous, mes connaissances aussi. Que puis-je pour vous, $N ?"] = "7f25bf796f093ccde831db9e50079867",
            ["Qu'Élune soit avec vous, $c."] = "9f0b1ccaf183a8e36a2849671ae33e26",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
            ["Élune soit avec vous, $c."] = "9f0b1ccaf183a8e36a2849671ae33e26",
        },
        [11401] = {
            ["Ma sagesse est à vous, mes connaissances aussi. Que puis-je pour vous, $N ?"] = "7f25bf796f093ccde831db9e50079867",
            ["Qu'Élune soit avec vous, $c."] = "9f0b1ccaf183a8e36a2849671ae33e26",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
            ["Élune soit avec vous, $c."] = "9f0b1ccaf183a8e36a2849671ae33e26",
        },
        [11406] = {
            ["J'espère que la Lumière est avec vous, $N. En quoi puis-je vous aider ?"] = "238a7cdf16a7d258e1b3789d98c5e7fb",
            ["Que la Lumière vous protège, $c."] = "852369f0d2fbc11e555e75fe5a433853",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "31ab172e1a375db1c9157d594eb608d9",
        },
        [11407] = {
            ["Je cherche quelqu'un, $c. Laissez-moi... Il est important que je le trouve."] = "139d2506ed562303b66f560b7502291c",
        },
        [11486] = {
            ["J’ai gouverné ce royaume pendant dix mille ans. J’ai entendu bien des récits fascinants de la part de ceux qui cherchent à pénétrer dans la demeure sacrée de la Maison de Shen’dralar.$B$BÉtant lié à cet endroit, j’échange souvent des histoires avec les visiteurs. Avez-vous une histoire pour moi ? À moins que vous ne souhaitiez entendre une histoire ?"] = "fb9a6eb92214ce1abb9831293212112b",
        },
        [11536] = {
            ["Certainement, $n. Il vous suffit de me dire sur quel niveau de réputation vous désirez des informations."] = "95455c097e5501d0311f370c9de61cc0",
            ["Certainement, $n.$B$BLes aventuriers considérés comme amicaux par l’Aube doivent soumettre un total combiné de 60 insignes pour avoir accès à des objets de qualité supérieure. Pour avoir accès à des objets encore plus puissants, ils doivent nous remettre 220 insignes.$B$BJe reconnais que pour ceux qui ne sont pas en faveur auprès de l’Aube, le prix est vraiment élevé."] = "9656dc4e19c25b00c359bd5324e01c23",
            ["Certainement, $n.$B$BLes aventuriers exaltés par l’Aube doivent soumettre un total combiné de 12 insignes pour avoir accès à des objets de qualité supérieure. Pour avoir accès à des objets encore plus puissants, ils doivent nous remettre 54 insignes.$B$BJe reconnais que c’est un prix élevé, même pour ceux qui sont exaltés au sein de l’Aube."] = "784b321e46fc302d5772086f42f3d4e4",
            ["Certainement, $n.$B$BLes aventuriers honorés par l’Aube doivent soumettre un total combiné de 14 insignes pour avoir accès à des objets de qualité supérieure. Pour avoir accès à des objets encore plus puissants, ils doivent nous remettre 90 insignes.$B$BJe reconnais que c’est un prix élevé, même pour ceux qui sont révérés au sein de l’Aube."] = "dcf21ea6bba24a55d9157c1f031d42ef",
            ["Certainement, $n.$B$BLes aventuriers honorés par l’Aube doivent soumettre un total combiné de 40 insignes pour avoir accès à des objets de qualité supérieure. Pour avoir accès à des objets encore plus puissants, ils doivent nous remettre 150 insignes.$B$BJe reconnais que c’est un prix élevé, même pour ceux qui sont honorés au sein de l’Aube."] = "c5a566d78a559292a57e527462eed009",
            ["Salutations, $c. Je suis Miranda Breechlock, l'une des rares intendantes en charge de l'équipement et du matériel pour l'Aube d'argent.$B$BCombattez le mal au travers des missions que nous avons à vous confier, gagnez notre respect et notre confiance, et le duc Zverenhoff vous attribuera des marques de valeur. Ces marques ont deux usages. Tout d'abord, elles vous permettent d'améliorer votre statut dans nos rangs. Elles servent également de monnaie d'échange pour acheter certains objets.$B$BVous verrez qu'en progressant dans les rangs de l'Aube d'argent, vous vous verrez proposer un nombre croissant d'objets."] = "76e62df07e05db88a7485a8b88c9987d",
        },
        [11548] = {
            ["Autrefois les Bien-nés dirigeaient une grande ville des elfes de la nuit et y pratiquaient une puissante magie des arcanes. Désormais ils sont maudits et hantent les terres. Leur ville en ruines a été victime des nagas Fouette-bile. Apparemment, les nagas fouillent les ruines à la recherche de reliques des Bien-nés."] = "177b136c703d996695ff9d9a6ee3304e",
            ["J’ai vu de terribles choses arriver aux furbolgs au cours des dernières années. Ils ont été des victimes, un peu partout. Mais j'ignore ce qu'il est advenu des membres de cette tribu. Ont-ils été atteints par la peste qui ravage Gangrebois ? Ou sont-ils furieux de ce qui est arrivé à leur peuple, naguère pacifique, et ils cherchent désormais à se défendre... Dans tous les cas, la plupart d'entre eux se montrent hostiles envers ceux qui entrent dans cette région."] = "b660919fd15bb4acba5ab26eedc550ac",
            ["Les dragons bleus ne sont pas là, mais les disciples de Malygos s'y trouvent. Je ne sais pas pourquoi, mais je peux vous dire ceci : quel que soit l'endroit où se trouvent les dragons bleus, attendez-vous à trouver de la magie des arcanes. Je ne serais pas surpris si les draconides étaient là, à protéger quelque chose... peut-être quelque chose que les Bien-nés ont laissé derrière eux."] = "ff66933a79e40c4363ca877e0bc40aab",
            ["Ma connaissance de l'histoire elfique est limitée, mais on dit qu'il y a longtemps, lorsque les elfes de la nuit tenaient pour sacrée la magie des arcanes, Azshara était la plus grande d'entre eux. Une très belle femme, qu’ils appelaient leur reine. Malheureusement, c'est son addiction à la magie qui allait déclencher les événements les plus sanglants que notre monde ait connus."] = "cadc0e431f4794433c9f20b321f3f84d",
            ["On dit qu'un puissant mage humain vit au nord. Il veillerait sur cette région pour une raison inconnue. Je n'y suis pas allé moi-même, mais on dit que les visiteurs sont les bienvenus et peuvent même gagner ses faveurs s'ils accomplissent quelques tâches pour lui."] = "ce97a3f0d9b87cbf8e4913c174a68681",
            ["Parce que vous m'avez aidé, je vais vous dire ce que je sais de ce pays. Mes connaissances ne sont pas très vastes, mais il y a certaines choses qui peuvent intéresser quelqu'un comme vous."] = "898b582dd44193bf71686d4995bc5367",
            ["Salutations, $c.$B$BCes Sentinelles m'ont autorisé à partager leur campement, tant que je me tiens tranquille. Je pense que vous comprenez qu'il est parfois nécessaire de faire preuve de diplomatie, surtout par ici, non ?$B$BJ'enquête sur certaines perturbations dans les terres, et comme cela soutient leur cause, ils ont compris que ma présence ici ne pouvait que favoriser l'alliance ténue qui unit toutes les races d'Azeroth. Si vous voulez m'aider, j'accepterai volontiers, mais quoi qu'il en soit, ne faites rien d'insensé."] = "f54143d6861ddef271769d60b550b493",
        },
        [11596] = {
            ["Mon plan d'entreprise n'a jamais tenu compte de l'hébergement de kodos géants... j'aurais peut-être dû me lancer dans le tressage de paniers sous-marins à la place."] = "f09ae60bd463ebe5e4647fdabaf33b7a",
        },
        [11608] = {
            ["Bonjour, $c. Je me suis établi ici, à la Barricade, pour me préparer à mon voyage dans les Maleterres. Il paraît qu'un grand mage humain s'est installé dans Hearthglen il y a quelque temps. La Croisade écarlate lui a donné pour mission de fabriquer les arcs et les fusils de ses guerriers et chasseurs. On dit qu'il a fabriqué une arme remarquable avant d'être tué par la Croisade.$B$BJe pense qu'ils ont de moins en moins confiance dans les arcanes."] = "bfa0aecd4815be32da4962b7c6f07ffe",
        },
        [11609] = {
            ["Salutations, $c. Je n'ai guère le temps de parler, je ne me sers du camp du Noroît que pour me reposer avant de partir pour Hearthglen. On dit qu'avant de devenir fous, les types de la Croisade écarlate avaient un mage avec eux, qui essayait de créer des arcs et des fusils puissants pour leurs troupes. J'ignore s'il a réussi ou non... La Croisade l'a tué avant qu'il n'ait terminé sa tâche. Peut-être l'ont-ils éliminé pour conserver un secret... ou peut-être haïssent-ils les arcanes..."] = "ce388452c2e07ab97505e895497f397f",
        },
        [11610] = {
            ["Heu... Bonjour, $n. Mille pardons, je me remets de mes blessures.$B$BCes types de la Croisade écarlate sont plus solides que je ne pensais. Ils m'ont presque eue.$B$BFaites bien attention, vous aussi. Je ne voudrais pas qu'ils vous fassent du mal."] = "5255d112e3f4d77633395a63b892be9f",
        },
        [11615] = {
            ["Ma famille travaillait dans la scierie de la Crête du nord, dans ce qu'on appelle maintenant les Maleterres de l'ouest. Ils étaient dévoués à la famille Dumah, et maintenant la Croisade écarlate s'en est emparée avec tout Hearthglen !$B$BJe n'aurai pas de repos tant que ces fanatiques n'auront pas été chassés d'Azeroth."] = "14f0d1fdd7afc2ea46056b354eced4c0",
        },
        [11616] = {
            ["Il y a longtemps, avant la dernière grande guerre, mon père dirigeait la scierie de la Crête du nord. C'était sa vie, et il s'y consacrait complètement. Puis la guerre est venue et, la mort dans l'âme, nous avons fui vers Stormwind.$B$BNous avons perdu bien des amis et des proches à l'époque, et j'ai le regret de dire que la Croisade écarlate s'est emparée de notre scierie.$B$BC'est pour ça que je suis revenu."] = "09280c8a100dbf6ab274fcbdf0803b69",
        },
        [11625] = {
            ["Ah... $gUn client:Une cliente; ! Parlez à ma plus belle invention, le Vendeurotron 1000. Il a tout ce que vous pouvez vouloir... Quelques-uns des objets les plus rares que l'on puisse trouver à Kalimdor... Sans compter que sa programmation ne permet aucun marchandage. Le prix que vous voyez, c'est le prix que vous payez."] = "4de54f822df981ac699c8e0f5d6eaca4",
        },
        [11626] = {
            ["C'est votre jour de chance, je viens de terminer la maintenance du Super-Vendeur 680. Il y a des tonnes d'objets à vendre à des prix imbattables. Allez, voyez vous-même... Mon frère Cork pense que son Vendeurotron 1000 se vendra mieux que mon automate."] = "f3da952cbd390a3e587b455be7a2577f",
        },
        [11798] = {
            ["Dans la forêt des Pins argentés, le long de la côte nord, une épave de bateau gît sur la berge. À l'ouest de l'épave se trouve ce que vous cherchez. Si vous nagez trop loin, la fatigue aura raison de vous. L'objet est au fond de l'océan, dans une boîte verrouillée, attendant que vous vous en empariez.$B$BIl ne sera pas simple de survivre à une plongée dans de telles profondeurs, mais il existe une fissure bouillonnante qui permet aux plongeurs cherchant cette moitié du Pendentif de reprendre leur souffle. Utilisez-la avec sagesse."] = "8f4726b4aaa640c64d970e27f5507d9f",
            ["Si vous cherchez un vol jusqu'au village de Rut'heran, parlez à mon alter ego chez les elfes de la nuit, Silva Fil'naveth."] = "e06e352070d1d0f09e52dc97d8a078e5",
            ["Voulez-vous un vol jusqu'à Thunder Bluff, aux frais du Cercle cénarien ?"] = "155c5f7fcaa47599e5718aa28c430db2",
            ["Vous devez chercher dans les eaux de la marche de l'Ouest, à l'ouest-nord-ouest de l'endroit où la carrière de la Côte de l'or rejoint le rivage. Une ancre indique l’endroit où un navire a coulé en eaux profondes. La pression sous-marine y est intense et peut venir à bout du plus solide des nageurs.$B$BPour vous aider, cherchez une formation naturelle, $n, elle abrite une fissure bouillonnante. Les bulles qui s'en échappent permettent aux plongeurs de reprendre leur souffle."] = "58917c8c3ab49673db3986c9f9ce7b31",
            ["Vous n'êtes pas druide !"] = "5cfd7206f10c06184a22b230f17e7e9b",
        },
        [11799] = {
            ["Le sanctuaire de Remulos est un lieu saint pour nous, membres du Cercle cénarien, ici à Reflet-de-Lune... Alors conduisez-vous d'une manière qui convient à un hôte.$B$BUn hôte qui ne souhaite pas servir de râtelier à mon sabre..."] = "2e8e186a35fdbdc4167c9a2d1cbd23c8",
        },
        [11800] = {
            ["Au nord de Sombrivage se trouve la Bondissante, une rivière qui provient des terres que nous appelons désormais Gangrebois. Tout comme la rivière coule vers la Lisière des brumes, allez au nord, là où l'océan se montre le plus profond. Vous trouverez ce que vous cherchez près d'une formation rocheuse que certains appellent la Griffe de pierre à cause de sa forme.$B$BAttention : les batteurs sont nombreux près de la Griffe de pierre, et ils attaquent tous ceux qui pénètrent sur leur territoire."] = "3d6d602f1e2f055fef17cf3368d58ec6",
            ["Au nord-est des Tarides, il existe une étendue d'eau polluée. Les habitants du coin l'appellent la Videfange. La KapitalRisk a transformé ces eaux naguère cristallines en un dépotoir de produits chimiques et de déchets industriels. Au cœur de ce marais se trouve ce que vous cherchez, $n.$B$BFaites attention, la KapitalRisk n'aime pas les intrus et quiconque ne travaille pas pour elle EST un intrus. Vous serez une cible privilégiée en tant que protecteur de la nature. Ils n'aiment pas trop les gens comme vous."] = "94a4bfe6c74514d3611a508fc1a3f472",
            ["Si vous cherchez un vol de retour pour Thunder Bluff, allez voir mon collègue tauren, Bunthen Plainswind."] = "cbbd89806b3ea7f79bc9dbdcee8cdcb8",
            ["Voulez-vous voler jusqu'au village de Rut'theran, aux frais du Cercle cénarien ?"] = "cfbd485026f0de1a03206ff943a27ce2",
            ["Vous n'êtes pas druide !"] = "b6d7af778c178854770fdd337d5b015a",
        },
        [11801] = {
            ["Au temps jadis, Eldre’Thalas était un nexus magique, et ceux qui vivaient dans ses salles sacrées contrôlaient un pouvoir immense… Parmi eux se trouvait une elfe de la nuit nommée Milicent Serene, une naturaliste qui introduisait le pouvoir de la nature lui-même dans les puissants objets magiques qu’elle forgeait.$B$BSon chef-d’œuvre fut le Fruit de la Fertilité… elle se servit d’un puits de lune spécialement préparé pour faire pousser une vigne exotique qu’elle dota d’une aura de croissance et de protection. Tout Eldre’Thalas profita de son existence, et la ville fut plus florissante que jamais."] = "308540acd4522979045cee37918c6a8c",
            ["Comme toujours, hélas. Comme tout le reste du Cercle cénarien, j’avais supposé que la création de Milli avait été détruite lors de la Guerre des Anciens. Mais j’ai fini par apprendre que j’étais dans l’erreur.$B$BLe Fruit de Fertilité a survécu… mais maintenant, on l’appelle la Gangrevigne. Elle a été corrompue par le seigneur démoniaque de cette partie d’Eldre’Thalas, Alzzin le Modeleur."] = "7eb5b4d204e4e905b3fc4a03671e7928",
            ["Je… je ne peux même pas commencer à l’imaginer, $n. Tout ce que je sais, c’est qu’il n’est pas question que cela se produise. Elle doit être détruite, à la fois pour nous protéger de la corruption démoniaque et pour honorer la mémoire de Millicent Serene… Milli…$B$BEt c’est là, mon $gami:amie;, que j’espère que vous allez intervenir."] = "a9d5f6215316701664aa2f69863fa29a",
            ["Les agents du Cercle cénarien ont découvert des informations inquiétantes à propos de la situation à Eldre’Thalas. Je suis dans une impasse, ne sachant pas quoi faire à ce sujet, mais je vais prochainement chercher l’aide d’individus capables de se battre.$B$BToutefois, pour agir de manière intelligente à Eldre’Thalas, il est important de connaître l’histoire d’un objet, le Fruit de Fertilité."] = "7a3713e922465a73a16446086589817a",
            ["N'écoutez pas les coeurs du monde. La vérité est à l'intérieur. Vous savez la vérité."] = "f4177bd0951c2f715a697139a8a7c918",
            ["Oui, mais je le connais sous son véritable nom, Eldre’Thalas. C’était un bastion de la magie des elfes de la nuit il y a maintes et maintes années.$B$BVous avez entendu parler d’Eldre’Thalas, mon enfant ? Compte tenu de mon problème présent, on pourrait croire à une coïncidence… mais je ne crois pas aux coïncidences."] = "888a945f04773f48531be690856af34d",
        },
        [11802] = {
            ["Salutations, $c. Je vous souhaite la bienvenue à Havrenuit, comme à Reflet-de-Lune. Le Cercle cénarien accueille tous les êtres qui respectent l'autorité et les ordres de la nature.$B$BTant que vous êtes ici, assurez-vous que vous préservez l'équilibre de toutes choses. Ici les troubles sont mal acceptés, et nos gardiens sont entraînés à faire cesser toute hostilité, sans poser de question."] = "628e4025e875b588722edea856c7e595",
        },
        [11811] = {
            ["<Narain tient une enveloppe fermée contre son front.>$B$BQu'est-ce que... Mmmm... Velours !$B$BEst-ce que j'ai raison ?"] = "225eafda96d1c24ae14477251f082c90",
            ["C'est... C'est très brumeux, $N. Je n'y vois rien ! Attendez... Attendez une minute. Je vois... Je vois le repaire du docteur Weavil. Il... OUI ! Je crois qu'il tient un chapitre du livre !$B$BVoyons si j'arrive à zoomer pour avoir un meilleur point de vue.$B$B<Narain a l'air de loucher.>$B$BL'île d'Alcaz ! Ce bâtard sournois est sur l'île d'Alcaz !"] = "fe83661210697890e5faa8788183a890",
            ["Narain Soothfancy, à votre service ! Ingénieur à la retraite et maître devin ! Je peux vous prédire votre avenir avant même qu'il ne se produise !"] = "2494fd01fbbcaa3067f0f6bde8276ef1",
            ["Ne me dites rien ! Chut ! Vous êtes ici au sujet du Porte-cendres ?!? Oui... Oui... Non ! Au temps pour moi.$B$BQue puis-je faire pour vous aider, $r ?"] = "2e27a2e4cf3cdc84c5efe6482fb8f345",
        },
        [11833] = {
            ["N'hésitez pas à venir me parler, $n. Vous avez bien servi Magatha. Je pense qu'elle fera de nouveau appel à vous dans le futur."] = "eeabcd657e17f9388ad202c9e2e118d7",
            ["Salutations, $c. Vous pouvez me parler, à moins de n'avoir à discuter directement avec ma maîtresse Magatha.$B$BJe m'occupe de la plupart des choses pour elle, afin qu'elle puisse se concentrer sur des choses plus importantes. Peut-être pouvons-nous parler ensemble avant que vous ne lui demandiez audience ?"] = "d3cf6d45a6ea3ef19313a80754b85210",
        },
        [11835] = {
            ["Bonjour, $n."] = "384ac0a49aebaacce2b295d67b189472",
        },
        [11860] = {
            ["J'ai peur de ne plus être ni aimable ni humble. L'âge et les combats innombrables ont endurci ma chair et mon âme. C'est peut-être pour cela que Cairne m'a affecté à la Retraite de Roche-Soleil... Les vents délicats et la chaleur du soleil adoucissent la douleur."] = "e07000c6839ce000b1b16c6b15d0533f",
        },
        [11861] = {
            ["Les Serres-Rocheuses sont truffées de cavernes dangereuses. Les explorer offre bien des aventures à ceux qui sont prêts à risquer leur vie pour la gloire.$B$B$C, peut-être cherchez-vous des richesses que seuls votre cœur et votre âme peuvent vous donner."] = "09ad1d72371134696f00bc0ad18afa09",
        },
        [11865] = {
            ["Bixi Wobblebonk, le Maître d'armes des gnomes, est quelque part dans cette échoppe. Elle peut vous apprendre à vous servir des arbalètes, des dagues et des armes de jet.  Woo Ping, le Maître d'armes des humains, se trouve à l'Arsenal de Weller dans Stormwind. Il vous initiera aux arbalètes, aux dagues, aux épées à une et deux mains, aux armes d'hast et aux bâtons.  Ilyenia Moonfire, Maître d'armes des elfes de la nuit, se trouve à la Terrasse des guerriers de Darnassus. Elle vous apprendra à utiliser les arcs, les dagues, les armes de pugilat, les bâtons et les armes de jet."] = "907cb6456b6c5ff065e865380e9b9180",
            ["Vous voulez apprendre l'utilisation d'une arme, n'est-ce pas ? Ne restez pas là comme une cruche, parlez !"] = "944b95dab7611ca743debffc47ea0d42",
        },
        [11866] = {
            ["Buliwyf, le Maître d'armes des nains aux Armes de Timberline, à Ironforge, saura vous apprendre le maniement des armes de pugilat, des fusils, des haches à une et deux mains et des masses à une et deux mains.  Bixi Wobblebonk, le Maître d'armes des gnomes, se trouve aux Armes de Timberline d'Ironforge, elle vous enseignera l'utilisation des arbalètes, des dagues et des armes de jet.  Woo Ping, le Maître d'armes des humains, se trouve à l'Arsenal de Weller de Stormwind. Il vous apprendra l'usage des arbalètes, des dagues, des épées à une et deux mains, des armes d'hast et des bâtons."] = "d360ac04210d718276dddc83f8708938",
            ["La grâce avec laquelle je me bats n'est pas quelque chose que je peux enseigner, mais je peux vous apprendre à utiliser différentes armes."] = "2e514c1eb9b20edc5d2084e30fe9df15",
        },
        [11867] = {
            ["Buliwyf, le maître d'armes des nains, est aux Armes de Timberline à Ironforge. Il saura vous apprendre à manier les armes de pugilat, les fusils, les haches à une et deux mains et les masses à une et deux mains.  Bixi Wobblebonk, le maître d'armes des gnomes, se trouve aux Armes de Timberline d'Ironforge. Elle vous enseignera l'utilisation des arbalètes, des dagues et des armes de jet.  Ilyenia, le maître d'armes des elfes de la nuit, se trouve à la Terrasse des guerriers de Darnassus. Elle vous apprendra à utiliser les arcs, les dagues, les armes de poing, les bâtons et les armes de jet."] = "0cf4036d40658806b00933ae705fa922",
            ["Êtes-vous ici pour apprendre l'art du combat armé ?"] = "da8269ec529338fb71da4bda52aa2d08",
        },
        [11868] = {
            ["Ansekhwa, le maître d'armes des taurens, est à Thunder Bluff, sur la Côte inférieure. Il vous apprendra à utiliser les masses à une et deux mains, les bâtons et les fusils.  Hanashi, qui est à côté de moi, peut vous apprendre à utiliser les arcs, les haches à une et deux mains, les bâtons et toutes sortes d'armes de jet.  Archibald, le maître d'armes des morts-vivants, se trouve au Quartier de la guerre d'Undercity. Il peut vous initier aux arbalètes, aux dagues, aux épées à une et deux mains et aux armes d'hast."] = "6fbe1caacff7fcf16cc0478c2dccd149",
            ["Vous êtes là pour apprendre à manier une nouvelle arme, ou seulement pour me faire perdre mon temps ?"] = "ac6104deed8fed0d5a86bb3bee66c1bd",
        },
        [11869] = {
            ["Ce sera un honneur pour moi de vous apprendre à utiliser les armes que je maîtrise, si vous avez la capacité d'apprendre."] = "c180df78a79d05ea8d63a60886eb2a84",
            ["Sayoc est le maître d'armes des orcs. On le trouve dans la Vallée de l'Honneur d'Orgrimmar. Il vous apprendra à utiliser les arcs, les dagues, les armes de pugilat, les haches à deux mains et les armes de jet.  Hanashi, le maître d'armes des trolls, habite la Vallée de l'Honneur d'Orgrimmar. Il saura vous apprendre à utiliser les arcs, les haches à une et deux mains, les bâtons et les armes de jet.  Archibald, le maître d'armes des morts-vivants, se trouve dans le Quartier de la guerre d'Undercity. Il vous apprendra l'usage des arbalètes, des dagues, des épées à une et deux mains et des armes d'hast."] = "abac3599f5c7bf1790a96604da9b81dc",
        },
        [11870] = {
            ["Je suppose que vous venez apprendre l'utilisation d'une nouvelle arme ? Faites vite, je n'ai pas le temps de m'amuser."] = "cebc5bda58373eb38beb32738253fcd6",
            ["Sayoc est le maître d'armes des orcs. Il se trouve dans la Vallée de l'Honneur d'Orgrimmar. Il vous apprendra à vous servir des arcs, des dagues, des armes de pugilat, des haches à une et deux mains et des armes de jet.  Hanashi, le maître d'armes des trolls, habite la Vallée de l'Honneur à Orgrimmar. Il vous enseignera à utiliser les arcs, les haches à une et deux mains, les bâtons et les armes de jet.  Ansekhwa, le maître d'armes des taurens, se trouve sur la Côte inférieure de Thunder Bluff. Il vous apprendra à maîtriser les masses à une et deux mains, les bâtons et les fusils."] = "1e08fa1b1a06707d7772a9d8bffbb01c",
        },
        [11872] = {
            ["Les temps sont périlleux, voyagez avec prudence."] = "6010e5908eacadb88d4696fee457da3a",
            ["Vous avez besoin d'une illusion ?$B$BSi votre illusion flanche au milieu de votre quête, revenez me voir et je vous offrirai de nouveau le déguisement.$B$BSi vous échouez, n'abandonnez pas ! Revenez me voir, je vous aiderai jusqu'à ce que vous ayez atteint vos objectifs."] = "326d109a3f8c03ee97228b860a23d901",
        },
        [11878] = {
            ["Encore $gun autre débile mental envoyé:une autre débile mentale envoyée; par la Dame noire pour recevoir l'entraînement de son champion.$B$B<Nathanos soupire.>$B$BJe les lui ai tous renvoyés en plusieurs morceaux, je ne vois pas pourquoi ce serait différent cette fois.$B$BMais je n'ai pas à discuter, je fais ce que demande la Dame noire."] = "36ceb7cebed57b0d09e09d90cea831c6",
        },
        [11899] = {
            ["Où voulez-vous aller ?"] = "0edd3c73540d735f036ac6e027466523",
        },
        [11900] = {
            ["Où voulez-vous aller ?"] = "f686b3319d4af5004c6ee3403aea3f5e",
        },
        [11901] = {
            ["Où voulez-vous aller ?"] = "f686b3319d4af5004c6ee3403aea3f5e",
        },
        [11939] = {
            ["Si vous cherchez des informations que le Cercle cénarien pourrait avoir archivées quelque part, c'est à moi qu'il faut parler. Mais vous devez savoir quelles informations vous cherchez avant que je ne puisse vous aider.$B$BVous comprenez comment ça marche maintenant ? Parfait !"] = "310c9f80926c7ac56d95a59b469ade54",
        },
        [12031] = {
            ["Il nous faudrait engager de l'aide. Je n'aime pas rester là toute la journée à vendre des accessoires de pêche. Je préférerais aller à la pêche moi-même, puis m'occuper de mon étal."] = "6c9f3fe4497da2c378cdd9d41104d24e",
        },
        [12032] = {
            ["Je n’ai plus rien à vous apprendre. J’ai entendu dire qu’à Baie-du-Butin, le Vieil Heming avait des exemplaires de « Vous et la perche ». Ça vous aidera sûrement à progresser."] = "0e953fd8dfbfe1414c60a2989878d380",
            ["Je peux vous apprendre à pêcher."] = "7709fb559a1b486ad6fbaec0f8f6f8ff",
            ["Pour progresser, vous avez besoin de trouver Nat Pagle, qui vit dans le marécage d'Âprefange."] = "191f9771bbe3c0dfd9d726fd4f02d760",
        },
        [12042] = {
            ["Bienvenue, $gmon frère:ma sœur;. Si vous êtes ici pour apprendre, j'aurai grand plaisir à vous enseigner.$B$BBientôt, vous entendrez l'appel du Rêve d'émeraude. Vous hibernerez pendant des années et marcherez parmi les formes les plus pures. C'est là que votre ultime formation aura lieu."] = "1d12fd8e421d229eea70c7677a2daeca",
            ["Même entre de froids murs de pierre comme ceux qui entourent cette ville, on peut trouver la tranquillité et la paix. En fait, on peut les trouver où qu'on soit... Il faut chercher en soi cet équilibre..."] = "922a94a8f826437fe0370bdcd6a587ac",
        },
        [12136] = {
            ["$gSalut, beauté, vous cherchez à aller jusqu'à Grom'gol ? Il paraît que ça chauffe pas mal dans ces jungles, je pourrais peut-être prendre quelques vacances avec vous, vous montrer deux ou trois aspects... de la vie sauvage. : Allez ! Faites un voyage dans les magnifiques et luxuriantes jungles tropicales de Strangleronce. C'est ça, vous aussi vous pourriez prendre le soleil près des eaux cristallines pendant que je reste ici sous un soleil de plomb, sans rien d'autre à faire que de regarder toute la journée mon frère Frezza ! Bon voyage !;"] = "808af6c85a55d2308db805b9fb00b368",
        },
        [12137] = {
            ["Glissez une petite pièce dans la main du chef et voyez où cela mène. J'aime mon travail. Mais si je connaissais le moyen de faire affecter cette canaille de Snurk à ce port... Enfin, à quoi bon. Mais je parie que vous n'êtes pas là pour parler de ça. Vous cherchez le zeppelin pour Undercity, non ? Eh bien c'est parfait, parce qu'on embarque là, juste derrière moi. Et si vous voyez Snurk, dites-lui bien des choses de ma part, d'accord ?"] = "c021420a6f84c190718c0e399aad7e67",
        },
        [12196] = {
            ["Ancienne capitale des nains Sombrefer, ce labyrinthe volcanique est aujourd'hui le siège du pouvoir de Ragnaros, le seigneur du Feu. Ragnaros a découvert le secret permettant de créer la vie à partir de la pierre, et a l'intention de construire une armée de golems invincibles pour conquérir le mont Blackrock. Obsédé par sa volonté de vaincre Nefarian et ses séides draconiques, Ragnaros ne reculera devant rien pour obtenir la victoire finale."] = "1a4b0ce90f4422503651666ac7f00711",
            ["Autrefois joyau de la région nord du Lordaeron, la cité de Stratholme est l'endroit où le prince Arthas se retourna contre son mentor, Uther Lightbringer, et massacra des centaines de ses propres sujets qu'il croyait contaminés par la peste des morts-vivants. La soumission d'Arthas au roi-liche suivit peu de temps après. La cité brisée est maintenant habitée par les morts-vivants du Fléau, dirigés par la puissante liche Kel'Thuzad et un contingent des Croisés écarlates commandé par le Grand croisé Dathrohan. Les deux camps s'affrontent dans un combat violent et permanent."] = "04642b49605c1905f8c4ec074ed814b2",
            ["Autrefois le plus grand centre de production d'or des terres humaines, les Mortemines sont maintenant habitées par la Confrérie Défias. Celle-ci a fait de ces sombres tunnels son sanctuaire privé. La rumeur affirme que ces voleurs ont engagé d'astucieux gobelins, qui les aident à construire une chose terrible dans les profondeurs des mines. Mais nul ne sait ce dont il s'agit. On murmure que l'entrée des Mortemines se trouverait dans le tranquille et modeste village de Ruisselune."] = "3ea6a13fe8e0d78eb57bd98488901e1a",
            ["Cette ville écrasée par le soleil est la demeure des trolls Sandfury, célèbres pour leur cruauté impitoyable et leur sombre mysticisme. Les légendes des trolls parlent d'une épée puissante appelée Sul'thraze la Flagellante, capable de provoquer la peur et d'affaiblir même les ennemis les plus puissants. En de temps lointains, l'arme fut brisée en deux. Des rumeurs affirment que les deux moitiés de cette épée fabuleuse se trouveraient quelque part derrière les murs de Zul'Farrak."] = "1362d50a99d5220c57eabff16d1c603a",
            ["Construite il y a douze mille ans par un ordre secret de sorciers elfes de la nuit, l'antique cité d'Eldre'Thalas protégeait les plus précieux secrets arcaniques de la reine Azshara. Elle fut ravagée par la Grande Fracture, mais la plus grande partie de ses merveilleux bâtiments survécut. Les trois quartiers distincts des ruines ont été envahis par toutes sortes de créatures, dont des Biens-nés spectraux, des satyres répugnants et des ogres brutaux, ce qui valut un nouveau nom à la cité : Hache-Tripes !"] = "c2a3a1e19674bf1fea64aea4440edb67",
            ["Construites dans les mêmes lianes que le Kraal de Tranchebauge, les Souilles de Tranchebauge sont la capitale traditionnelle du peuple huran. Ce gigantesque labyrinthe d'épineux abrite une véritable armée de hurans loyaux ainsi que leurs grands prêtres : l'ordre de la Tête de Mort. Cependant, une ombre s'est récemment étendue sur leurs repaires sommaires. Des agents du Fléau – dirigés par la liche Amnennar le Porte-froid – ont pris le contrôle du peuple des hurans, et ont transformé le labyrinthe d'épineux en un bastion des morts-vivants."] = "d204a8a00341a429174e0dbb644ab882",
            ["Durant la Guerre des Anciens, le demi-dieu Agamaggan vint affronter la Légion ardente. Ce sanglier colossal fut vaincu, et avec le temps, aux endroits où son sang avait coulé, d'énormes lianes épineuses poussèrent. Les hurans finirent par occuper ces terres, les considérant comme sacrées. Au cœur de ces immenses colonies d'épineux se trouve Tranchebauge. Le kraal de Tranchebauge fut conquis par la mégère, Charlga Trancheflanc, que certains soupçonnent de négocier avec des agents du Fléau dans un but insidieux."] = "f92aaab1f1d5835cf040d33a901f8ac6",
            ["Frustré par le manque de résultats des sorciers de Dalaran dans le combat contre les morts-vivants durant la Troisième guerre, l'archimage Arugal décida d'invoquer des worgens venus d'une autre dimension pour renforcer son camp. Les hommes-loups massacrèrent les troupes du Fléau, puis se retournèrent rapidement contre les sorciers. Ils assiégèrent le donjon du noble baron d'Argelaine, qui tomba rapidement et devint la proie des ombres. Rendu fou par la culpabilité, Arugal adopta les worgen qu'il considéra comme ses enfants, et se terra dans le fort qui fut dès lors appelé le donjon d'Ombrecroc."] = "12f0b7117e82d1920705e38b1acbd4d3",
            ["Gnomeregan se trouve dans l'ouest de Dun Morogh."] = "2a62241f7676852d758c2bff35cb1c86",
            ["Il y a plus d'un millier d'années, un groupe de prêtres trolls appelés les Atal'ai tenta de faire revenir un ancien dieu sanguinaire nommé Hakkar, l'Écorcheur des âmes. Durant la guerre civile qui s'ensuivit, les prêtres furent vaincus et exilés dans le marais des Chagrins. C'est là qu'ils érigèrent un temple voué à Hakkar, pour préparer son arrivée sur le monde matériel. L'Aspect dragon Ysera eut bientôt connaissance de leurs plans et engloutit le temple dans les marais. Jusqu'à aujourd'hui, les ruines du temple sont gardées par de puissants dragons verts."] = "356949e6616d911ef559b61355e02894",
            ["L'entrée des cavernes des Lamentations se trouve à l'oasis Luxuriante au sud-ouest de la Croisée dans les Tarides."] = "73249f674e33dc5e663d9bf0dc9c96b6",
            ["L'école de nécromancie connue sous le nom de Scholomance se trouve sur l'île ravagée de Caer Darrow dans les Maleterres de l'Ouest."] = "e68483a569e848b8cb7bca2cf17765d1",
            ["La Scholomance se trouve dans les cryptes du donjon de Caer Darrow. Appartenant autrefois à la noble famille Barov, le donjon est tombé en ruines après la Deuxième guerre. Quand le sorcier Kel'Thuzad recrutait des fidèles pour son culte des damnés, il promettait souvent l'immortalité à ceux qui servaient son roi-liche. Les Barov tombèrent sous son influence et lui offrirent leur donjon, mais les sectateurs tuèrent la famille et transformèrent les cryptes en une école de nécromancie. Bien que Kel'Thuzad n'habite plus ici, les sectateurs et les instructeurs du culte y vivent encore…"] = "210c73367be3bd7fff9c76683b08beeb",
            ["La prison de Stormwind est un complexe pénitentiaire de haute sécurité, construit sous le quartier des canaux de la ville. Dirigée par le gardien Thelwater, elle abrite de petits escrocs, des prisonniers politiques, des meurtriers et une vingtaine des criminels les plus dangereux du pays. Récemment, une révolte de détenus a semé le chaos dans la prison, d'où les gardiens ont été chassés et où les condamnés circulent en toute liberté."] = "39d92fa9357e241705910cea426d1baf",
            ["La prison de Stormwind se trouve près du quartier des mages, à Stormwind."] = "5a680486b1eed5318ac671810b927e65",
            ["La puissante forteresse creusée dans les entrailles brûlantes du mont Blackrock était en possession des sinistres nains Sombrefer depuis des siècles, quand Nefarian, le fils rusé du dragon Aile de mort, s'empara de la zone supérieure du pic. Il fit alors la guerre aux nains dans les profondeurs volcaniques de la montagne. Comprenant que les nains étaient dirigés par le puissant élémentaire du feu Ragnaros, Nefarian fit le vœu d'écraser ses ennemis et de s'emparer de la totalité du mont Blackrock."] = "12696642ffca20488693f012a1332369",
            ["La ville ravagée de Stratholme se trouve dans les Maleterres de l'est au nord de Pestebois."] = "50d79c7aeabf3cffea9b701bf10738f2",
            ["Le Gouffre de Ragefeu est un ensemble de cavernes volcaniques qui se trouvent sous Orgrimmar, la nouvelle capitale des orcs. Des rumeurs selon lesquelles un culte fidèle au démoniaque Conseil des ombres s'est établi dans les profondeurs rougeoyantes du Gouffre ont récemment circulé. Ce culte, connu sous le nom de Lame ardente, menace la souveraineté même de Durotar. Beaucoup pensent que le chef de guerre orc, Thrall, connaît son existence et a délibérément choisi de ne pas le détruire dans l'espoir que ses membres pourraient le conduire vers le Conseil des ombres."] = "470d4f471ff0e0a695c417d93294115b",
            ["Le Gouffre de Ragefeu se trouve sous la Faille de l'Ombre au centre d'Orgrimmar."] = "b589ee74b06baa0850c27cb5b2dced61",
            ["Le Temple englouti se trouve au centre d'un grand lac dans l'est du marais des Chagrins."] = "839365eaa1b7bc650b1f66d477413bef",
            ["Le donjon d'Ombrecroc se trouve dans le sud des Pins argentés juste au nord de Bois-du-Bûcher."] = "149d727e2252ad2d21626074d67ae0be",
            ["Le kraal de Tranchebauge se trouve à l'extrémité sud des Tarides du côté ouest de la route."] = "22e76f151640be474a52357149eab9fa",
            ["Le monastère Écarlate se trouve dans les collines au nord-est des clairières de Tirisfal."] = "3549cdf0ffdc4b960c88a13a92c251c5",
            ["Le monastère était autrefois un lieu d'instruction et de prière. Lors de l'arrivée du Fléau mort-vivant durant la Troisième guerre, le paisible monastère fut converti en forteresse par les fanatiques de la Croisade écarlate. Les croisés détestent toutes les races non-humaines, quelle que soit leur alliance ou leur affiliation. Ils pensent que tous les étrangers sont des porteurs potentiels de la maladie des morts-vivants… et qu'ils doivent être détruits."] = "b4ca0c190cfd0a68f67e69a9ad1ec76b",
            ["Le mont Blackrock se trouve entre la gorge des Vents brûlants au nord et les Steppes ardentes au sud."] = "42c37076d3ae3863acfdd2d0f5533f7a",
            ["Les Mortemines se trouvent au-dessous de Ruisselune dans le sud de la marche de l'Ouest."] = "45dbe29f976fe7758380dadfd1b0d5ec",
            ["Les Profondeurs de Brassenoire se trouvent à l'extrémité nord de la grève de Zoram le long de la côte d'Ashenvale."] = "31b8782bafa771a039b08f6726b827a8",
            ["Les Souilles de Tranchebauge se trouvent à l'extrémité sud des Tarides, du côté est de la route."] = "5bb22872b7638f5085ca2059018cc5ff",
            ["Les gages d’amour sont de petits messages d’affection que vous pouvez donner aux habitants des villes et des capitales qui ont le cœur à l’amour. En échange, elles vous offriront un cadeau d’adoration.$B$BSi vous êtes déjà $gadoré:adorée; par quelqu’un d’autre, elles vous remettront au moins un cadeau d’amitié."] = "65a26145712718ab736d0dff25b7ea3a",
            ["Les ruines de Hache-Tripes se trouvent au centre de Féralas."] = "59afccdff32f76ae9879d7192bc79e60",
            ["Les ruines de Zul'Farrak se situent dans le nord-ouest du désert de Tanaris."] = "bac84ba209bd32f334399053e2f4b16f",
            ["Maraudon est l'un des sites les plus sacrés de Désolace. Ce grand temple/caverne est le lieu de sépulture de Zaetar, l'un des deux fils immortels du demi-dieu Cénarius. La légende affirme que Zaetar et la princesse des élémentaires de la terre Theradras engendrèrent la race bâtarde des centaures. On dit qu'après leur naissance, les centaures barbares se retournèrent contre leur père et le tuèrent. Certains pensent que Theradras, rendue folle par le chagrin, emprisonna l'esprit de Zaetar dans la caverne labyrinthique, pour utiliser son énergie dans un noir dessein…"] = "73717c12f946e4832d3760a4ce017d6e",
            ["Maraudon se trouve au milieu de la côte ouest de Désolace, dans la Vallée des Lances."] = "ba011425ec6ef2499c76a0df8538827b",
            ["Moi non, mais beaucoup de gens cherchent l’amour. Vous devriez mettre un peu de parfum ou d’eau de Cologne, acheter mes gages d’amour, et les faire circuler !"] = "608e80af556ec1f3d3baef7e57f6be28",
            ["Quand vous donnez des gages d'amour aux habitants des villes, vous recevez différents cadeaux en retour. Vous pouvez en garder ou en utiliser certains, mais vous pouvez aussi en faire des assortiments que vous donnerez à votre héros préféré !$B$BAllez voir Kalin Colportecoeur pour donner vos cadeaux.$B$BVous pourrez trouver Kalin près de Bolvar, Magni et Tyrande."] = "598c9e84f0150f5804083fb81cddb144",
            ["Quand vous donnez des gages d'amour aux habitants des villes, vous recevez différents cadeaux en retour. Vous pouvez en garder ou en utiliser certains, mais vous pouvez aussi en faire des assortiments que vous donnerez à votre héros préféré !$B$BAllez voir Kalin Colportecoeur pour donner vos cadeaux.$B$BVous pourrez trouver Kalin près de Cairne, Sylvanas et Thrall."] = "661c2fbcff67197ca647909d6eff45c0",
            ["Si nous devons faire nôtres ces nouvelles terres, nous devons disposer d’endroits pour reposer nos corps épuisés par les combats. Déposez votre hache près du feu et partagez les récits de vos glorieuses batailles."] = "99898ce989e2387123a310f8e8bb7094",
            ["Si vous mettez de l’eau de Cologne ou du parfum, vous verrez qui a le cœur à l’amour. Tous acceptent les gages d’amour… et vous offrent un don en échange.$B$BAttention, pour donner un gage d’amour à quelqu’un, vous devez avoir la bonne odeur. Les hommes aiment l’odeur du parfum, et les femmes celles de l’eau de Cologne."] = "11667b0ff9532331158f6482eeb8d71d",
            ["Situé à Dun Morogh, Gnomeregan est la capitale des gnomes depuis des générations, même si elle a été récemment infestée par des troggs mutants. Lors de l'attaque des troggs, dans une tentative désespérée de représailles, le Grand Bricoleur Mekkatorque ordonna la vidange d'urgence des réservoirs de déchets radioactifs de la ville. Même irradiés, les troggs maintinrent leur siège et les gnomes furent obligés de trouver refuge dans la cité naine d'Ironforge; C'est là que le Grand Bricoleur recrute des âmes hardies pour aider son peuple à reconquérir sa chère cité."] = "0276ff49074261ee804b38342793bf84",
            ["Situées sur la grève de Zoram, en Ashenvale, les Profondeurs de Brassenoire étaient autrefois un magnifique temple voué à la déesse de la lune des elfes de la nuit, Elune. Malheureusement, la Grande Fracture détruisit en partie le sanctuaire, l'engloutissant sous les eaux de la Mer voilée. Il y resta, intact, jusqu'à ce qu'attirés par son pouvoir ancien, les nagas et les satyres le fouillent pour s'emparer de ses secrets. Les légende affirment qu'une bête ancienne, Aku'mai, s'est installée dans les ruines du temple."] = "799c250c21ae02bcb1dbb537a38580f9",
            ["Souhaitez-vous explorer l'un de ces donjons ?"] = "f3aba6e9ee464fd9569a3498cd66780a",
            ["Uldaman est l'ancien domaine des titans, enterré sous des tonnes de terre depuis la création du monde. Les fouilles menées par les nains dans cette cité ont récemment libéré les premières créations manquées des titans : les troggs. Selon les légendes, les titans estimèrent que l'expérience des troggs était un échec. Mais ils firent une nouvelle tentative, qui leur permit de créer la race des nains. Ces secrets sont inscrits sur les mythiques Disques de Norgannon – d'immenses artéfacts qui reposent dans les profondeurs de l'ancienne cité, protégés par des créatures géantes façonnées dans de la pierre vivante."] = "533b295b436d39d2d08b9a0010da7943",
            ["Uldaman se trouve à l'extrémité nord des Terres ingrates."] = "72fd07384c9cf3d35d09b60e74ac757b",
            ["Un elfe de la nuit dénommé Naralex a récemment découvert qu'un réseau de cavernes souterraines se dissimulait au cœur des Tarides. Croyant qu'il pouvait utiliser les sources de ces cavernes pour rendre leur fertilité aux Tarides, le druide commença à aspirer l'énergie du légendaire Rêve d'émeraude. Mais sa vision s'est transformée en cauchemar, et peu à peu les cavernes des Lamentations sont devenues le repaire de prédateurs cruels et dangereux. On dit que Naralex réside encore dans ce labyrinthe, emprisonné derrière les barrières du Rêve d'émeraude."] = "c5bb28585e4ec2284a09cc538e5ea938",
        },
        [12197] = {
            ["$N, avez-vous la moindre idée de ce qui se passe dans la vallée d’Alterac ? Êtes-vous de taille à combattre le clan Frostwolf ?"] = "fe70eb05a6a384f2150bdbcaad041ebd",
        },
        [12198] = {
            ["Je regrette, $c, mais vous devez gagner en force avant que je vous permette d'entrer dans le bassin d'Arathi."] = "5d7befc434c3b284ff699c9b717bf554",
            ["Vous croyez-vous de taille à détruire la Ligue d’Arathor, $c ? Je l’espère, en tout cas. Que voulez-vous ? Êtes-vous là pour me faire perdre mon temps ?"] = "59736d80c4279b69db8e94d24074d17a",
        },
        [12340] = {
            ["Si vous cherchez à chasser des nagas, vous aurez besoin de toute l'aide possible. Au fond de l'eau, vous trouverez des fissures bouillonnantes, qui fournissent assez de bulles d'air pour vous permettre de respirer sous l'eau. Nagez assez près pour utiliser ces bulles."] = "3c57610ceaac598ea2221dac45d2551c",
        },
        [12384] = {
            ["Avant la venue du Fléau, j'avais un bon commerce. J'achetais et je vendais de tout. De tout !$B$BEt mes prix étaient DÉMENTIELS !$B$BDemandez à n'importe qui. À ceux qui ne sont pas morts."] = "9735b7ad56c5248bbce82ee64ea4959d",
            ["Salut $N ! Êtes-vous là pour acheter quelque chose ? Pour vendre quelque chose peut-être ?$B$BVous ne trouverez pas de meilleurs prix ailleurs, ou alors mon nom n'est pas Augustus !"] = "337f7913cf78a0dd090124d95e4642d6",
        },
        [12577] = {
            ["Où voulez-vous aller ?"] = "8ee9e2b8b1fbeba82851331d36cb251c",
        },
        [12578] = {
            ["Où voulez-vous aller ?"] = "e9f2c6ae11c08606a3e902729508a45b",
        },
        [12596] = {
            ["Où voulez-vous aller ?"] = "4a4d46597b846228dbd070932127a575",
        },
        [12616] = {
            ["Où voulez-vous aller ?"] = "0edd3c73540d735f036ac6e027466523",
        },
        [12617] = {
            ["Où voulez-vous aller ?"] = "43540ff7458382b18eb66468d4ff2856",
        },
        [12636] = {
            ["Où voulez-vous aller ?"] = "99afa7bbff40b3ecca37eb15b8c29387",
        },
        [12656] = {
            ["Sur le quai nord, vous pouvez embarquer sur un navire qui vous transportera au village de Rutheran et à Darnassus. À partir du quai sud, vous pouvez traverser la Grande mer jusqu'au Port de Menethil sur Khaz Modan. Puisse votre voyage se dérouler sans encombre !"] = "69d07a52e02e6c2a801dd6309215b6e6",
        },
        [12657] = {
            ["Ce quai ? Vous pouvez attraper le navire qui se rend quelque part chez les elfes de la nuit. Hum, à Auberdine je crois. Je ne suis pas vraiment sûr. Je ne fais que charger et décharger des marchandises."] = "ca7d18cf048257b8138d41171774e437",
        },
        [12658] = {
            ["Vous trouverez un passage vers Theramore depuis ce dock. Mais écoutez-moi bien : il est dangereux de traverser ces terres pour les membres de l'Alliance. Protégez vos arrières."] = "0330eb47812f7e68da55bc38f1165206",
        },
        [12696] = {
            ["Cet ours suit une voie proche de la Perce des Serres, à l'ouest du Lac Mystral et de l'Avant-poste que l'Alliance a placé au Refuge de Vent-argent. C'est la moins terrible des trois créatures que vous affronterez dans la Chasse d'Ashenvale, mais ne baissez tout de même pas votre garde. Sa présence est une menace permanente pour les voyageurs qui vont d'Ashenvale aux Serres-Rocheuses."] = "d1f866875591d687da8e4a807ff8fed2",
            ["Entendez-vous l'appel de la chasse, $c ? Vous devez écouter attentivement, l'appel vient des profondeurs de votre être. De notre être à tous."] = "d6db8cda45395ece303eac030d3ff6f3",
            ["On dit que ce sabre-de-nuit est docile en présence des elfes de la nuit et de leurs alliés, ce qui en fait un adversaire encore plus valable. Le territoire de chasse de Shadumbra va de la Retraite de Raynewood, à l'ouest d'ici, jusqu'à loin au ponant. Sa fourrure est noire comme une galaxie morte et il ne faut pas sous-estimer sa rapidité."] = "12b6c7a941e965437e30f09d3a14b002",
            ["Serres-tranchantes est la bête la plus puissante à affronter au cours de la Chasse d'Ashenvale. Elle est libre de ses mouvements, avec la bénédiction des gardiens auto-proclamés de cette terre, les elfes de la nuit. Serres-tranchantes cherche ses proies au sud de cette zone et prend plaisir à déchiqueter les voyageurs innocents.$B$BAbattre une telle créature ne sera pas un mince exploit, $N. Je vous souhaite bonne chance !"] = "dab92356ed8e0a6f55c5ecdea69948a1",
        },
        [12716] = {
            ["J'aime à m'asseoir ici et à écouter la musique de la Grande mer. Oh, pardon ? Oui, il y a un navire que vous pouvez prendre jusqu'au port de Menethil. Il s'ancre ici de temps en temps."] = "3999a32253abe70964154c372f32bc5f",
        },
        [12724] = {
            ["Cette forêt peut faire perdre le sens de l'orientation. Faites attention là-dedans."] = "6021998ac094693ef86cf366f8e389f8",
        },
        [12736] = {
            ["Les éléments nous parlent, $c. Ils partagent les connaissances que nous devons apprendre et les secrets qui doivent être gardés."] = "0a8aa26eccc0242964a89762467e5241",
        },
        [12737] = {
            ["Si vous cherchez des informations sur les déplacements des caravanes et des marchands au poste de Bois-Brisé, alors je suis l'orc de la situation. Malheureusement pour vous, je n'aime pas les gens.$B$BAlors soyez $gbref:brève;."] = "0d07f0a4ca3a5cd318acb1ed5b17e3de",
        },
        [12740] = {
            ["Où voulez-vous aller ?"] = "f686b3319d4af5004c6ee3403aea3f5e",
        },
        [12757] = {
            ["Salutations, $c. Bienvenue sur le front, dans notre combat pour la conquête d'Ashenvale ! Si vous cherchez quelque chose à faire, vous êtes au bon endroit ! Je suis toujours à la recherche d'individus capables de m'aider à accroître la gloire de la Horde !"] = "373a32e64da03908f74c18135f0f399a",
        },
        [12776] = {
            ["Vous n'êtes pas démoniste et je n'ai pas de temps pour vous. Filez !"] = "200fc4a4b57ca0db7de99023c501ea23",
            ["Vous voulez que vos démons soient plus puissants ? Cela vous coûtera cher, mais vous êtes au bon endroit."] = "4e1a9fddd86d3d21099d60aa02fea747",
        },
        [12807] = {
            ["Vous n'êtes pas démoniste et je n'ai pas de temps pour vous. Filez !"] = "1cb32f6470dcf1a2f6a434cc66bea835",
            ["Vous voulez que vos démons soient plus puissants ? Cela vous coûtera cher, mais vous êtes au bon endroit."] = "7890c2b1ae34d8a5d70574f03c64ac95",
        },
        [12863] = {
            ["Oui, $c ? Qu'avez-vous à dire ?"] = "ecb5c5765055132283e8f669c19aa1d7",
        },
        [12866] = {
            ["Je ne vous veux pas de mal. J'enquête sur les hurans et je prends des notes sur leurs moeurs. Mon peuple a remarqué quelque chose d'étrange, une sorte d'émanation maléfique, en provenance de cet endroit. Je suis là pour en apprendre plus, et ce que j'ai appris est inquiétant.$B$BIl semble qu'il y ait dans les parages un diplomate mort-vivant versé dans les arts des arcanes. Je ne crois pas que ce soit un des Réprouvés... Je pense que c'est pire que ça."] = "87ac0e81bb9a372fa977ea14e6844f6c",
        },
        [12919] = {
            ["Merci encore de m'avoir rapporté mon mètre ruban porte-bonheur, $N. Je vous assure qu'il m'aide à attraper de plus gros poissons !"] = "4b8c6e9b9c6223f29c6ee50817bd5289",
            ["Pour attraper Gahz'ranka, il vous faudra un appât spécial au puant de vase. Je les fais moi-même !$B$BMais l’appât ne suffit pas, vous aurez aussi besoin de puants de vase… Vous devez les placer dans l’appât de manière à ce qu’il pue horriblement ! Lorsque vous aurez les puants de vase, jetez l’appât au large de la pointe de Pagle à Zul’Gurub… Vous n’avez plus qu’à vous servir à boire et à attendre… mais pas longtemps, parce que Gahz'ranka ne tardera pas, c’est sûr !"] = "bb7840ac1ccbf51d87e9a44ee1a98d48",
            ["Si vous voulez mon avis, ce qu'il y a de mieux dans la pêche, c'est la lenteur. Ça laisse le temps de réfléchir, de penser aux événements passés et de préparer l'avenir.$B$BOh, et c'est aussi une très bonne excuse pour boire. Beaucoup."] = "9d7745f7746667248f72319a9c4794ef",
        },
        [12920] = {
            ["Quel plaisir de vous revoir, docteur $n. J'ai suivi vos progrès et je dois dire que vous êtes désormais en mesure d'apprendre des techniques de bandage plus avancées.$B$BRevenez me voir de temps en temps, au fur et à mesure que vos compétences s'étofferont, je vous apprendrai tout ce que je sais."] = "adcbd8c041c99ea585dd49cda036f459",
            ["Salutations, $n. Je suis le docteur Gregory Victor, chirurgien-chef de l'unité médicale de la Horde."] = "2638fdc24fed03d3d2affc64eca0bf76",
            ["Vous avez appris tout ce que je peux vous enseigner pour l'instant, docteur $n. Revenez me voir lorsque vous aurez un peu de pratique, et je vous apprendrai des facettes plus avancées de l'art médical."] = "283509ff38d5fe49b3dd45d5e0947aad",
        },
        [12939] = {
            ["Quel plaisir de vous revoir, docteur $n. J'ai suivi vos progrès et je dois dire que vous êtes désormais en mesure d'apprendre des techniques de bandage plus avancées.$B$BRevenez me voir de temps en temps, au fur et à mesure que vos compétences s'étofferont, je vous apprendrai tout ce que je sais."] = "f4e3a2c79c79518799f91abcc4d1c545",
            ["Salutations, $n. Je suis le docteur Gustaf VanHowzen, chirurgien-chef de l'unité médicale de l'Alliance."] = "0ba18a644f30676df3277200c1ada92e",
            ["Vous avez appris tout ce que je peux vous enseigner pour l'instant, docteur $n. Revenez me voir lorsque vous aurez un peu de pratique, et je vous apprendrai des facettes plus avancées de l'art médical."] = "b4c40d18e1bc694e2ebd862b96fbe637",
        },
        [12944] = {
            ["En échange d’un lingot de Sulfuron, je suis autorisé à vous communiquer un exemplaire des plans qui permettent de forger un marteau de Sulfuron.$B$BBien sûr, vous vous dites « pourquoi m’encombrer d’un tel marteau, puisque j’ai déjà des armes meilleures ? » Eh bien, laissez-moi vous dire quelque chose, mon $gami:amie;, il n’existe rien de supérieur à ce qu’un marteau de Sulfuron peut devenir !"] = "2d38739dd99aac211a82868d39e682e5",
            ["La Confrérie du Thorium ne perd pas son temps avec des fourmis. Partez !"] = "807f545aa510396b39fd74ed72c9abcb",
            ["La Confrérie du thorium dispose des connaissances nécessaires pour forger les bras sacrés et l'armement du seigneur du Feu, mais nous n'avons pas la main-d'œuvre pour collecter les matériaux indispensables.$B$BMoi, Lokhtos Darkbargainer, j'ai été chargé par la confrérie d'échanger les recettes contre du matériau en provenance du Cœur du Magma.$B$BPrésentez votre offre, $r."] = "30d968320ab86521f066be7db8986c04",
            ["Tout ce que vous avez à faire, c'est forger le marteau de Sulfuron et trouver l’Oeil de Sulfuras. Combinez l’Oeil de Sulfuras et le marteau de Sulfuron, et ils deviennent du Sulfuras ! Notez bien que je ne vais pas vous embêter avec des détails techniques. À vous de découvrir où et comment vous pourrez récupérer un Oeil de Sulfuras. Signez juste ce contrat, afin que nous soyons liés par un accord écrit. Ensuite, notre affaire sera conclue."] = "436fa6a143302d46598f8cf4299ea9d9",
            ["Un lingot de Sulfuron ? Impossible ! Je dois l’avoir ! Je le dois !$B$BCher $r, je suis autorisé à vous offrir beaucoup de choses en échange de ce lingot. Les secrets de la Main de Ragnaros vous intéresseraient-ils ? Sulfuras, idiot ! Le légendaire marteau du seigneur du Feu !"] = "ffe6ef04a13e4da40d3147386221790a",
        },
        [12961] = {
            ["Je n’ai plus rien à vous apprendre. J’ai entendu dire qu’à Baie-du-Butin, le Vieil Heming avait des exemplaires de « Vous et la perche ». Ça vous aidera sûrement à progresser."] = "0e953fd8dfbfe1414c60a2989878d380",
            ["Je peux vous apprendre à pêcher."] = "7709fb559a1b486ad6fbaec0f8f6f8ff",
            ["Pour progresser, vous avez besoin de trouver Nat Pagle, qui vit dans le marécage d'Âprefange."] = "191f9771bbe3c0dfd9d726fd4f02d760",
        },
        [12996] = {
            ["$N, la Ligue d’Arathor tente de reprendre ses terres ancestrales du bassin d’Arathi aux Réprouvés. Si vous voulez l’aider, parlez à Donal Osgood dans le Hall des Armes."] = "44b04e19a4aa4b719b00c378a9acd900",
            ["Ah, Braenna Flintcrag. Elle a des mains magiques, celle-là ! Braenna est celle qu'il faut voir pour les affaires des prêtres.   Allez au nord depuis les portes d'Ironforge jusqu'au Hall des mystères. C'est là que vous la trouverez."] = "59e9a008fc9fe41cf912bf06861683df",
            ["Ah, je crois que Gimble Thistlefuzz est la personne dont vous avez besoin pour devenir Enchanteur ! Vous trouverez Gimble dans son échoppe, les Arcanes de Thistlefuzz, près du Maître des gryphons de la Grande Forge."] = "6e1942115134fa4728a8bd01469f0ee2",
            ["Ah, la vallée d’Alterac ! De grands souvenirs ! <soupir> Bon, je ne peux pas vous y envoyer, mais ça m’a quand même fait plaisir d’y penser ! Pour y aller, vous devrez parler à Glordrum Steelbeard, dans le Hall des Armes, ici à Ironforge."] = "e06fd55d9c7b155fdb8e8ed8c2d4b286",
            ["Ah, le bon vieux Brandur Ironhammer. Je suis sûr qu'il vous donnera l'aide que vous désirez. Vous le trouverez au Hall des mystères, au nord des portes d'Ironforge."] = "63f213a9fe7d396bded4b0fcdb6f51b1",
            ["Ah, rien ne vaut un prêtre pour guérir les blessures. Bien sûr, une bonne bière aide aussi, mais je ne pense pas que Braenna Flintcrag enseigne la fermentation. Cela dit, vous trouverez bien un prêtre pour vous instruire au Hall des mystères."] = "c813addf44eeb3041f9442747e4f19b7",
            ["Ah, rien ne vaut une bonne promenade en gryphon, pas vrai ? Les elfes de la nuit peuvent se garder leurs hippos, pour moi rien de tel que les bons vieux gryphons !   Mais je ne veux pas vous retarder, allez voir Gryth Thurden à l'est de la Grande Forge. Il vous mettra sur la route."] = "cb6734d0257007705c4566a44b980164",
            ["Alors comme ça, $ggamin:gamine;, vous croyez avoir ce qu’il faut pour défendre l’Alliance face à la Horde dans la vallée d’Alterac ? Très bien ! Dans ce cas, parlez à Glordrum Steelbeard, ici même à Ironforge. Vous le trouverez dans le Hall des Armes, en train de définir des stratégies devant la table de guerre."] = "f0b32b90ead935933c43bb1468fa3f95",
            ["Avez-vous le potentiel pour devenir un chasseur expérimenté ? Le temps nous le dira... Mais n'essayez pas de tirer sur des pommes placées sur la tête des gens tant que vous n'aurez pas parlé à Regnus dans le Hall des Armes."] = "4ee53decdddf5b8264e87b7865aae7ab",
            ["Bah ! Les boîtes aux lettres... Je ne reçois que de la pub ces temps-ci...    Agrandissez la taille de ceci.... Diminuez la taille de cela... En prime, notre cadeau : l'Épée de destruction des dragons ! Il faut que je change d'adresse tous les deux mois !    Enfin, je vous ai $gprévenu:prévenue; ! Si vous cherchez la boîte aux lettres, elle est à la sortie de la taverne de Stonefire."] = "cc8d5bdde66d34c96aeda15e29b244e5",
            ["Balthus Stoneflayer est celui qu'il faut voir pour le Dépeçage. Il vous apprendra tout ce qu'il faut. Allez jusqu'aux Cuirs de Finespindle, au nord de la Grande Forge."] = "19d7a62aa644748c5d13eaad7341a221",
            ["Bixi et Buliwyf ont dû écraser ou taillader des orcs avec à peu près tous les types d'armes existant. Vous les trouverez près des Armes de Timberline si vous avez besoin d'une formation."] = "96990add552d311d4fe9f5b1e0e496d4",
            ["Brandur Ironhammer est celui que vous devez voir. Vous le trouverez au Hall des mystères, au nord des portes d'Ironforge."] = "31c78e407d6e78277f84d7122edc2533",
            ["C'est l'artisanat qui vous intéresse ? Pas de doute, il faut aller voir Springspindle Fizzlegear, à Brikabrok.   Allez à l'est des portes d'Ironforge, ou suivez le bruit des explosions."] = "6edc9f2da8079aff91202f55fb3e3dc7",
            ["Ce Jormund Stonebrow a un don pour l'aiguille, pas de doute. Si vous avez besoin de leçons, vous le trouverez aux Vêtements de Stonebrow, au nord de la Grande Forge."] = "759b920689d00afab4a880a03c8bd208",
            ["Cette petite Bink, là-bas dans le Hall des mystères, serait sans doute capable de satisfaire tous vos besoins en matière de magie.   Le Hall des mystères est au nord des portes d’Ironforge."] = "8d292d1b067d993333147a509e6e409c",
            ["Dans le Hall des Armes, vous trouverez notre Maître des écuries local, Ulbrek Firehand. Il prendra soin de tous les familiers que vous lui confierez."] = "8417670da6e88a3c0046fbf19a284faf",
            ["Eh bien... Vous êtes au bon endroit pour apprendre à miner. Geofram Bouldertoe lui-même se trouve à la Guilde des mineurs de la montagne profonde. Il n'y a pas de meilleur instructeur que lui."] = "57c3f67ebbf0020b5e1987aa2869782f",
            ["Fimble Finespindle a une échoppe au nord-ouest de la Grande Forge. Je parie qu'il pourrait vous montrer comment faire de belles armures."] = "e6b5bccb2a9112e11e11306a28cbcb09",
            ["Grimnur Stonebrand a tendance à raconter des bobards ahurissants, mais c'est quand même l'un des meilleurs pêcheurs du coin. Il a une échoppe dans la caverne lugubre, le Pêcheur itinérant."] = "0ddcbbb7af1ef15099416e16690edff4",
            ["Hé ! Vous devriez faire attention à ce que vous enchantez, $gl’ami:l’amie;. J’avais fait enchanter un bol pour qu’il ne renverse jamais une seule goutte. Du coup, impossible de boire avec, une vraie tragédie !   Tenez bien compte de mon conseil quand vous verrez Grimble. Vous le trouverez dans sa boutique, à proximité du Maître des gryphons, dans la Grande Forge."] = "5906a29765d2173d53b9ab776005d62b",
            ["Il ne faut pas manquer la moindre occasion de combattre la Horde, et tout particulièrement les orcs, si vous voulez mon avis. Vous pourrez vous battre tout votre saoul dans le goulet des Warsong, ça c’est sûr. Allez donc dans le Hall des armes pour parler à Lylandris. Elle vous indiquera la route à suivre."] = "fa89dafc6960a6d66ea3bc3288a08a03",
            ["J'ai entendu Regnus Thundergranite, au Hall des armes. Il se vantait d'un nouveau trophée l'autre jour. Si vous voulez être $gformé:formée; par un chasseur de talent, Regnus est l'homme à voir."] = "d93d0f3b1e5ea15a5dd989a27017ef56",
            ["J'ai entendu une fois Grimnur dire qu'il avait pêché un marteau. Ou c'était un requin-marteau, peut-être ? Fichu Grimnur, il a tellement raconté d'histoires de pêche que je ne me souviens plus... Bah, allez le voir dans la Caverne lugubre, il vous racontera ça mieux que moi."] = "b4e38865182ec7942e86379c3c9fcdf9",
            ["Kelstrum est un vantard, mais c'est aussi l'un des guerriers les plus expérimentés que vous rencontrerez jamais !   Je vous le dis, si vous voulez progresser en tant que guerrier, c'est à lui qu'il vous faut parler. Vous le trouverez sans nul doute au Hall des Armes, à l'est des portes d'Ironforge."] = "cbf2a15cc62d3fbd23d5f088837de2bf",
            ["L'auberge ? Ah oui ! Vous cherchez les meilleures bières de la région ? La Taverne de Stonefire, c'est là qu'il faut aller. $B$BVous la trouverez à gauche des portes d'Ironforge si vous entrez, à droite si vous sortez."] = "886fa9ce5bf2e50d6df39dca00c5e72c",
            ["La banque ? Ah, le Coffre ! Bien sûr ! Il n'y a pas d'endroits plus sûrs pour mettre des objets précieux ! Vous le trouverez au nord-est de l'entrée d'Ironforge."] = "726ce72b8aa754ecf613d9315fa35780",
            ["Le dépeçage ? À vous voir, c'est plutôt vous qui risquez le dépeçage. Ah ! Pourquoi n'allez-vous pas voir Balthus Stoneflayer, qu'il vous apprenne à dépecer correctement des animaux. Vous le trouverez à la boutique de marchandises en cuir de Finespindle, au nord de la Grande Forge."] = "5a0adca7c8c31d843cea219178821576",
            ["Le goulet des Warsong ? Eh bien, il faudra que vous parliez à la belle Lylandris, dans le Hall des armes."] = "65538115404a72c45137bf80f3f5572c",
            ["Les fleurs, les graines, tout ça ? C'est la branche de Reyna Stonebranch, si j'ose dire ! Vous la trouverez, les doigts dans l'humus, au Médecin d'Ironforge, au sud de la Grande Forge."] = "9341074330c1dbc19f8fdf714badbebf",
            ["Les humains ont besoin de notre aide dans leur combat contre les Réprouvés du bassin d’Arathi. Rendez-vous au Hall des Armes et parlez à leur représentant, Donal Osgood."] = "a551a630e051c403297c7c5b9ebba84b",
            ["Ma foi, vous aurez besoin de papiers pour former une guilde, et Jondor Steelbrow peut vous aider dans les premières étapes. Vous le dénicherez au Centre des visiteurs d'Ironforge quand vous serez $gprêt:prête;."] = "7b31a92e46c77d8643368a8d82916e89",
            ["Mais pourquoi voulez-vous les services d'un de ces types ? On a assez de problèmes avec ce voleur, Hulfdan Blackbeard, dans la caverne lugubre. Va-t-il falloir que je vous surveille aussi ?"] = "36ac17a15ff106629b6c52dbefcd7203",
            ["Och ! Ce Daryl Riknussun est un remarquable cuisinier. Il fait un chili si épicé qu'on pourrait y tremper une épée ! Je ne pense pas qu'il vous enseignera la recette, mais il vous aidera à devenir un bon cuistot. Vous le trouverez à la Bouilloire de bronze, au nord-est de la Grande Forge."] = "5a9c20e893c2fd018c67b13bea773ae2",
            ["Och ! Vous voulez devenir guerrier, hein ? Kelstrum Stonebreaker vous y aidera. Rendez-vous au Hall des armes, à l'est des portes d'Ironforge."] = "740a72f70d8805a7b803e0d29dbe0d05",
            ["Oh ! Vous voulez apprendre à ramasser des pâquerettes ? Ah, je plaisante !   C'est une respectable profession, et Reyna Stonebranch peut vous montrer en quoi elle consiste. Elle travaille au Médecin d'Ironforge, au sud de la Grande Forge."] = "9ba6396c2f8ca0fde5f32bf5810ac783",
            ["Oh, le tram, le tram... Tout le monde veut le tram. C'en est donc fini des bons vieux vols à dos de gryphon, quand on s'agrippe à la selle pour ne pas tomber du haut des cieux ?    Bah ! Allez prendre le tram si ça vous chante... C'est à Brikabrok, avec le reste des bidules gnomes."] = "b6f01b7cfb83b6af6ea28d402cd03b91",
            ["Oh, vous cherchez Springspindle Fizzlegear, dans ce cas. Ce petit gnome et ses gadgets... Je vais vous dire, si vous allez dans son échoppe de Brikabrok, faites attention où vous mettez les pieds et ne flattez pas ses moutons mécaniques !   Des moutons explosifs... Mais quelle idée !"] = "cb4411cf05a5193ed1592cf994d7a1e6",
            ["Oui, et quel champ de bataille cherchez-vous ?"] = "495cb758f46f91069a540dc47968d5b3",
            ["Oui, tout le monde veut prendre le tram. Ma foi, si vous voulez le trouver, il est à Brikabrok, à l'est des portes d'Ironforge."] = "e151e5a6629ea4a4c716bafbf9cf9641",
            ["Où chercher une engeance maléfique, sinon dans les recoins obscurs d'Ironforge, j'ai nommé la caverne lugubre ? Thistleheart y est sûrement, sans doute en train d'invoquer une créature répugnante."] = "205d885c660f13d010f41ecd69423cc6",
            ["Où est l'hôtel des ventes ? Juste à droite des portes d'Ironforge quand vous entrez dans la ville. Vous le trouverez juste en face de la chambre forte."] = "d6e64cdc436665776809311fd999e5cd",
            ["Où voulez-vous aller ?"] = "411e9efc17c0fa67fa3a65ddbceb693f",
            ["Premiers soins ? C'est bien utile ! Notre Maître local, Nissa Firestone, peut vous montrer comment l'on fait. Cherchez-la au sud de la Grande Forge, au Médecin d'Ironforge."] = "aa54bc8510198f4330f29e9a0b3eae00",
            ["Premiers soins ? Vous n'avez pas l'air d'avoir de blessures... Si vous voulez vraiment apprendre les Premiers soins, allez voir Nissa Firestone. Vous la trouverez près de la Grande Forge, dans son échoppe, le Médecin d'Ironforge."] = "acbd5104f14dbadffa1e4f40e28a6ffd",
            ["Prendre soin des animaux est quelque chose qu'Ulbrek Firehand fait avec beaucoup de consience professionnelle. Il traîne généralement avec les chasseurs au Hall des Armes, si vous voulez qu'il s'occupe de vos familiers."] = "02f503b66aaa06ff7cf2372c215ba1f0",
            ["Quel Maître de classe cherchez-vous ?"] = "dcadd0f33e63218ef70a191c145117f6",
            ["Quel maître cherchez-vous ?"] = "cf38911600ac02c04cb72aafa6596e66",
            ["Quel maître de classe cherchez-vous ?"] = "dcadd0f33e63218ef70a191c145117f6",
            ["Si nous avons des Maîtres des mineurs ici ? Vous nous prenez pour qui ?   Vous trouverez les meilleurs mineurs de tout Dun Morogh à la Guilde des mineurs de la montagne profonde, au nord de la Grande Forge. Là, Geofram Bouldertoe vous enseignera l'art véritable de la mine."] = "75e0a88cc8fcf68c42a9c9a4f31ea193",
            ["Si vous avez l'intention de former une guilde, vous devez rendre visite à Jondor Steelbrow au Centre des visiteurs d'Ironforge. Allez au sud-est à partir des portes d'Ironforge, vous finirez par le rencontrer."] = "67bc72e3f75682dc138f1d22ef089d92",
            ["Si vous cherchez une maison d'hôtes, l'auberge de Stonefire est le bon endroit. Elle se trouve à gauche des portes d'Ironforge si vous entrez, à droite si vous sortez. $B$BOh ! Et si vous allez par là, dites-leur de me mettre un tonneau de côté."] = "9678dcc90aee99c0461684dd12aa5a6d",
            ["Tous les types de ce genre sont dans la caverne lugubre, au nord des portes d'Ironforge. Je parie que vous y trouverez Fenthwick, sans doute en train de compter le butin d'une autre bourse dérobée. Je l'attraperai un de ces jours !   En attendant, je garderai aussi l'oeil sur vous, $gmon gars:ma fille;."] = "9528aea502ae9f7db96fe57bfe2c7e48",
            ["Un démoniste, hein... Ma foi, si ça vous branche de faire ce genre de trucs, par ici il vaut mieux garder vos démons en laisse, je vous préviens... Je n'aime pas les démons, mais j'aime bien leur fendre le crâne. Vous me comprenez ?   Maintenant laissez-moi et allez dans la Caverne lugubre. Vous y trouverez un démoniste appelé Thistleheart."] = "8dd3f0d79f6df157dda9178efcf166dd",
            ["Un maître des cuisiniers ? Eh bien, allez à la Bouilloire de bronze, au nord-est de la Grande Forge. Daryl Riknussun vous apprendra à cuisiner de bons plats qui réchaufferaient un mort !"] = "f62abc611ce83aa205cd0e2b5918cc10",
            ["Vous allez où ?"] = "411e9efc17c0fa67fa3a65ddbceb693f",
            ["Vous avez de nouveaux trésors que vous voulez mettre à l'abri ? Alors mieux vaut les mettre au Coffre des Stonemantle.   Vous le trouverez à un jet de marteau de l'entrée d'Ironforge, vers le nord-est."] = "d3430aba4fb0b400b8dca87cf1df8b15",
            ["Vous cherchez un Maître des Alchimistes ? Ça tombe bien, je viens d'en voir un. Vous trouverez Mme Berryfizz à Brikabrok, là où les gnomes s'assemblent."] = "76c8e36d99bf968b0318157d711f4ce3",
            ["Vous cherchez un maître des alchimistes ? Ça tombe bien, je viens d'en voir un. Vous trouverez Mme Berryfizz à Brikabrok, là où les gnomes s'assemblent.   ::soupir:: Mais pourquoi je n'ai pas pris la potion bleue ?"] = "10124c09c298bee683297933e30e1865",
            ["Vous l'ignorez peut-être, mais en plus d'être un tailleur expérimenté, Jormund est aussi un tueur de géants ! On était en train de parler de choses et d'autres quand il est arrivé en hurlant qu'il en avait tué sept d'un coup !   Allez le voir dans sa boutique, au nord de la Grande Forge. Il vous racontera tout."] = "c8b7cc29723f78c9a33d40dd94b43a31",
            ["Vous me demandez vraiment où est le Forgeron ? Vous n'avez pas entendu parler de la Grande Forge !? Nos meilleurs forgerons s'y rassemblent pour y fourbir leurs armes et armures !   C'est juste au milieu d'Ironforge, c'est là que vous trouverez l'un des plus grands d'entre eux, Bengus Deepforge."] = "79bd37ced9c62943a531dbe47af6053b",
            ["Vous pouvez trouver une boîte aux lettres à droite de la Taverne de Stonefire. C'est au nord des portes d'Ironforge."] = "164f8858641d9fa2782d051756979421",
            ["Vous trouverez à vous perfectionner dans les arts magiques au Hall des mystères, au nord des portes d'Ironforge. Juli Stormkettle s'y trouve toujours, le nez dans un bouquin."] = "7e98ceebc9414083a4cc3fb3ae42f394",
            ["Vous voulez apprendre à utiliser de nouvelles armes, pas vrai ? Ma foi, vous devriez parler à Bixi ou Buliwyf, aux Armes de Timberline. Ils savent tout utiliser, des arbalètes aux.. aux zweihanders !"] = "fc659204f3f853f42dd60c81107e99b8",
            ["Vous voulez faire une promenade en gryphon, hein ? Gryth Thurden est celui qu'il faut voir !  Vous le trouverez à l'est de la Grande Forge, au milieu d'Ironforge."] = "818c80ba62a6062182774f0d488d44b8",
            ["Vous êtes $gsûr:sûre; que vous ne voulez pas être Forgeron... Bon, si vous tenez vraiment au Travail du cuir, parlez donc à Fimble Finespindle, dans son échoppe au nord-ouest de la Grande Forge."] = "a3b00fdf92a61d7b9b93fae27791e95f",
            ["Vous êtes au bon endroit ! Les gens viennent ici de partout pour apprendre le métier de Forgeron. Vous trouverez Bengus Deepforge jouant du marteau près d'une enclume au milieu de notre belle ville, près de la Grande Forge elle-même."] = "2ffc912f1ac294a9f6bb188522b88c70",
        },
        [12997] = {
            ["Monty, que je m'appelle, et j'ai des rats à la pelle."] = "ca995c7f0f5f79ad1e87335c01749488",
        },
        [13000] = {
            ["Ces courses sont une belle occasion de faire valoir notre ingéniosité !"] = "88d6d4700d0a9435deac731bbef17f8c",
            ["J'ai installé un nouvel outil dans le régulomètre de la matrice du véhicule. Ça devrait augmenter le quotient de vitesse d'au moins quinze !"] = "bb2e2ac84fdaea93b4cb5f24ace4d539",
            ["Johnson ? Je pense qu’il se trouve quelque part dans les parages..."] = "5d227c61a514e3f0b41f912efe022c52",
            ["Le Brave ? Il paraît que le Maître des courses Kronkrider, là-haut, dans la tour, sait où il se trouve."] = "288dfdbe6b0b08a6f2781e22dc5d8ce0",
            ["Mon Almanacotron bidulique me dit que nous battrons les gobelins, avec 20 secondes d'avance de plus que la dernière fois !"] = "29cb9f241b67a6bd58f46757f27f6f9e",
            ["Mon fils peut fabriquer des véhicules plus rapides que ces vieux tas de ferraille gobelins !"] = "5a9bf6255acd34e980aebcd04a7a6def",
            ["Sans la chance invraisemblable des gobelins, ils s'écraseraient sur un arbre à chaque course !"] = "413ec8412f752d13ea7d3bc09e39592d",
            ["Tirth n’est plus tout à fait lui-même ces jours-ci, son assistant non plus d'ailleurs."] = "329639fd7e8c50ac0b798afe6c0f563e",
        },
        [13018] = {
            ["Vous ne trouverez pas de meilleur ragoût de rat de ce côté de Khaz Modan !"] = "d070931d907bc8487f4f4b1378bf8ea4",
        },
        [13084] = {
            ["Buliwyf, le maître d'armes des nains, est ici aux Armes de Timberline, il saura vous apprendre le maniement des armes de pugilat, des fusils, des haches à une et deux mains et des masses à une et deux mains.  Woo Ping, le maître d'armes des humains, se trouve à l'Arsenal de Weller de Stormwind. Il vous apprendra l'usage des arbalètes, des dagues, des épées à une et deux mains, des armes d'hast et des bâtons.  Ilyenia, le maître d'armes des elfes de la nuit, se trouve à la Terrasse des guerriers de Darnassus. Elle vous apprendra à utiliser les arcs, les dagues, les armes de poing, les bâtons et les armes de jet."] = "24fbc29bbfa684d547e89fb18cc02719",
            ["Salut ! Vous êtes là pour apprendre à utiliser correctement un nouvelle arme ?"] = "aca797c5fc53636876bb9796d70dee29",
        },
        [13177] = {
            ["Où voulez-vous aller ?"] = "f686b3319d4af5004c6ee3403aea3f5e",
        },
        [13220] = {
            ["Le passé vit ici, $c. Prenons garde à ne pas l'éveiller."] = "72d9e590ddf6bf219b208c8b157ddb5c",
        },
        [13283] = {
            ["Ce que j'enseigne ne risque pas de vous intéresser. Cherchez plutôt quelqu'un qui forme des gens de votre classe, $c."] = "0fac9f50e1fb5c48f7301ce81e131b5f",
            ["Je ne pense pas que vous souhaitiez apprendre rien de ce que j'enseigne. Cherchez un maître de votre classe pour vous aider, $c."] = "0fac9f50e1fb5c48f7301ce81e131b5f",
            ["Vous avez l'air de quelqu'un qui aime jouer avec les pièces d'or des autres. Je peux vous aider de quelque manière ?"] = "8ad40600a7b98e4dedc4ac4c244156c2",
            ["Vous êtes le genre de personne près de laquelle il faut surveiller sa bourse. Puis-je faire quelque chose pour vous aider ?"] = "8ad40600a7b98e4dedc4ac4c244156c2",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
        },
        [13320] = {
            ["Vous venez pour m'entendre parler de victoires et de défaites ? Sachez qu'ici, il n'y a pas de vainqueurs…"] = "1b77224af068edacdc86b986bb6acf01",
        },
        [13417] = {
            ["Les Esprits ont guidé votre être jusqu'à moi. En quoi puis-je vous être utile ?"] = "d96f407d05286ba207ff46bf75ef4510",
            ["Que les Esprits soient avec vous !"] = "1eec7529a102737979dbaf19908f6ac0",
            ["À travers un vigoureux recyclage, j'ai dû contraindre bien des étudiants à oublier ce qu'ils avaient appris, afin qu'ils soient prêts à recevoir mon enseignement. Le service que je propose devient de plus en plus difficile à accomplir. C'est pour cela que c'est sans cesse plus cher. Voulez-vous que je vous fasse oublier ce que vous avez appris ?"] = "9ccfbeb35c89e4770c3695a5c842eef7",
        },
        [13418] = {
            ["Bonnes fêtes du Voile d'hiver à tous ! Et pour bien commencer, foncez aux Gourmandises Fumebois pour vous faire plaisir !"] = "9e130ea2841a0a72d792c96c8e646148",
            ["C'est l'époque des bonnes affaires ! Fah la la la la !"] = "3fabe072e57d6a47c2f6ca2b9c8134a7",
            ["Directement de la ferme à votre assiette : les meilleurs produits sont ceux des Gourmandises Fumebois !"] = "33f7fa4705c0138ea7a4c54342903154",
            ["N'oubliez pas de dire au Grand-père Hiver quel cadeau vous voulez pour le Voile d'hiver !"] = "cc87a307413254d64af804bd33e37001",
            ["Ne lésinez pas sur les paquets cadeaux pendant le Voile d'hiver ! Rien ne vaut un beau noeud rose autour d'une hache ou d'une épée pour réjouir le coeur de vos amis !"] = "41e918ce5d8b5a41ff38961622d0549a",
            ["Rabais pour vous et pour les vôtres !"] = "6c6b13e6f0ac323bc0364cf61cf53234",
            ["Si j'avais des marrons, je les ferais cuire sur les braises en plein air ! Mmmm !"] = "b6dafafd31fc1556e3a2a4d282f57535",
            ["Vive le son des cloches, mais pas les trous dans les poches ! Grâce aux Gourmandises Fumebois, économisez sur vos dépenses pour le Voile d'hiver !"] = "ba70cc90cf6fed160c19534755c94deb",
        },
        [13420] = {
